INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1300b', 'spa', 'Relámpago: un destello de luz brillante en una tormenta; usado para teofanía divina, juicio y gloria deslumbrante. Denota el destello del relámpago qu', 'Relámpago: un destello de luz brillante en una tormenta; usado para teofanía divina, juicio y gloria deslumbrante. Denota el destello del relámpago que rasga el cielo durante una tormenta, pero en las Escrituras su alcance va mucho más allá de la meteorología. En el Sinaí, los relámpagos acompañaron truenos y densa nube cuando Dios descendió (Éx 19:16). El salmista celebra cómo los relámpagos de Dios iluminan el mundo y hacen temblar la tierra (Sal 97:4). En Deuteronomio 32:41, Dios afila su ''espada reluciente'' — el destello de una hoja. Nahúm 2:5 compara los carros con relámpagos por su velocidad. El término captura una brillantez vívida e instantánea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1301', 'spa', 'Barak (''relámpago''), hijo de Abinoam, líder militar que derrotó a Sísara bajo la dirección de Débora', 'Nombre propio del comandante israelita que, a instancias de la profetisa Débora, reunió a diez mil hombres de Neftalí y Zabulón para derrotar al general cananeo Sísara junto al torrente de Cisón (Jue 4–5). Su nombre significa ''relámpago'', cognado con el apellido púnico Barcas que llevaba la familia de Amílcar. Las trece apariciones se concentran en Jueces 4:6–22 y el Cántico de Débora en Jueces 5:1, 12, 15. Todas las traducciones principales — español, francés, alemán — simplemente transliteran el nombre como ''Barak''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1305', 'spa', 'Purificar, seleccionar o refinar — abarcando la purga moral, la elección de lo mejor y el afilado de armas. Abarca un vívido rango semántico desde el ', 'Purificar, seleccionar o refinar — abarcando la purga moral, la elección de lo mejor y el afilado de armas. Abarca un vívido rango semántico desde el fuego del refinador hasta la piedra de afilar del guerrero. En sus formas reflexivas (Nifal, Hitpael), describe mostrarse puro ante Dios — ''con el puro te muestras puro'' (2 S 22:27; Sal 18:26). Dios mismo ''purgará'' a los rebeldes de entre Israel (Ez 20:38). Como participio pasivo Qal, se desplaza hacia la selección y la calidad: guerreros escogidos (1 Cr 7:40; 9:22), ovejas selectas preparadas para la mesa del gobernador (Neh 5:18) y palabras que son ''puras'' o claras (Job 33:3). En el Hifil, adquiere un sentido marcadamente físico: afilar flechas para la batalla (Jer 51:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1308', 'spa', 'El Besor — un arroyo en el sur del territorio filisteo, cerca de Gaza', 'El arroyo de Besor marca un lugar crucial en la persecución de David contra los amalecitas que incendiaron Siclag (1 Sam 30). Doscientos de los hombres agotados de David se quedaron junto a este wadi mientras cuatrocientos continuaron la persecución. El arroyo se convirtió en escenario de un importante precedente legal: David dictaminó que quienes cuidaran el equipaje compartirían el botín en partes iguales con los que combatieron (1 Sam 30:21-25). La erudición moderna lo identifica con el Wadi Razze al suroeste de Gaza. El nombre podría relacionarse con una raíz que significa ''buena noticia'', aunque esto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1309', 'spa', 'noticia, nueva (especialmente buena nueva); también la recompensa dada al portador de la noticia', 'Sustantivo femenino que aparece en las narraciones de 2 Samuel y 2 Reyes, estrechamente ligado al drama de los mensajeros del campo de batalla. En la mayoría de sus ocurrencias significa simplemente «noticia» o «nueva», como cuando la corte de David aguarda noticias de la batalla contra Absalón (2 Sam 18:20-27). En 2 Reyes 7:9, los leprosos reconocen que su descubrimiento del campamento arameo abandonado es «buena nueva». Un sentido especializado aparece en 2 Samuel 4:10, donde denota la recompensa entregada al mensajero, el pago que se espera por traer noticias. El cognado árabe bisharah confirma el significado central de anuncio gozoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1310', 'spa', 'Hervir o cocinar alimentos en líquido (Piel); madurar o alcanzar la sazón de frutos o cosechas (Qal/Hifil)', 'Hervir o cocinar alimentos en líquido (Piel); madurar o alcanzar la sazón de frutos o cosechas (Qal/Hifil)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1314', 'spa', 'Especia, perfume, bálsamo — sustancia aromática usada en la unción sagrada, el incienso, el comercio y el tributo real', 'Especia, perfume, bálsamo — sustancia aromática usada en la unción sagrada, el incienso, el comercio y el tributo real');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1315', 'spa', 'Basemat — nombre propio femenino (''fragante''), llevado por esposas de Esaú y una hija de Salomón', 'Nombre propio femenino (בָּשְׂמַת) que probablemente significa ''fragante'' o ''perfume'', derivado de la raíz בשׂם (''especia, bálsamo''). Lo llevan al menos dos, posiblemente tres, mujeres en las Escrituras. En Génesis 26:34, Basemat es una esposa hitita de Esaú, hija de Elón. En Génesis 36:3, otra Basemat, hija de Ismael, también se casa con Esaú, lo que genera un conocido problema de armonización con el nombre Mahalat en Génesis 28:9. Una tercera Basemat aparece como hija de Salomón, casada con el gobernador Ahimaaz (1 Reyes 4:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1316', 'spa', 'Basán — la fértil región montañosa al este del Jordán, originalmente el reino de Og, famosa por su ganado y sus encinas.', 'Basán — la fértil región montañosa al este del Jordán, originalmente el reino de Og, famosa por su ganado y sus encinas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1319', 'spa', 'Llevar buenas nuevas, anunciar noticias gozosas — proclamar victoria, salvación o alegres nuevas (raíz Piel)', 'Llevar buenas nuevas, anunciar noticias gozosas — proclamar victoria, salvación o alegres nuevas (raíz Piel)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1320', 'spa', 'Carne; el cuerpo físico, tejido animal comestible o la piel exterior; la humanidad en su fragilidad ante Dios', 'בָּשָׂר es la palabra principal de la Biblia hebrea para la dimensión material y corpórea de los seres vivos. En su uso más común denota el cuerpo mismo — el ser físico de humanos y animales como algo distinto del espíritu o el alma, como cuando Dios declara ''No contenderá mi espíritu con el hombre para siempre, porque él es carne'' (Gn 6:3). Pero también se estrecha hacia lo concreto: la carne asada del cordero pascual (Ex 12:8), las porciones sacrificiales colocadas sobre el altar y la carne cotidiana de las comidas. En la legislación sacerdotal emerge un tercer sentido más especializado — la piel visible o superficie corporal inspeccionada por lepra, donde el suajili ngozi (''piel'') y el árabe بَشَرَة (''epidermis'') preservan el significado original de la raíz semítica con mayor transparencia que el español carne. En los tres sentidos, בָּשָׂר conlleva un matiz de vulnerabilidad y transitoriedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1321', 'spa', 'carne — voz aramea para la carne corporal o las criaturas vivientes en Daniel', 'Este sustantivo arameo es el equivalente del hebreo basar y aparece exclusivamente en las visiones de Daniel. Designa tanto la carne literal devorada por bestias (Dn 7:5) como, en sentido figurado, la humanidad o toda criatura viviente (Dn 2:11; 4:12). Comparte cognados con otros dialectos arameos (Targum, siríaco) y abarca el mismo campo semántico que su par hebreo: carne física, la condición mortal del ser humano y el ámbito de lo creado en contraste con lo divino. En Daniel 2:11 subraya la distancia insalvable entre los dioses y los mortales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1322', 'spa', 'Vergüenza, deshonra o humillación; también usado como sustituto escribal de Baal en nombres propios (Bosheth)', 'Vergüenza, deshonra o humillación; también usado como sustituto escribal de Baal en nombres propios (Bosheth)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1323', 'spa', 'Hija, descendiente femenina; figuradamente, aldea dependiente o poblado satélite de una ciudad mayor', 'בַּת es la contraparte femenina de בֵּן (hijo), y denota una hija en relación con sus padres. Sin embargo, su campo semántico se extiende mucho más allá de lo biológico: ''hijas de Sion'' designa a las mujeres — o a la comunidad — pertenecientes a Jerusalén, y ''hija'' como vocativo es un trato de ternura (Rt 2:8). De manera notable, בַּת desarrolla un sentido geográfico: las ''hijas'' de una ciudad son sus aldeas circundantes sin muralla, dependientes de la ciudad madre fortificada. Los traductores al español captan esto con viveza, pasando de hija a aldeas cuando el contexto lo exige (Jos 17:11; Nm 21:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1324', 'spa', 'Bato, unidad hebrea de medida para líquidos (~22 litros), usada para vino, aceite y otros líquidos', 'Unidad de capacidad para líquidos en el sistema de medidas del antiguo Israel, equivalente a unos 22 litros o 6 galones estadounidenses. Era la contrapartida líquida del efa seco, siendo ambos una décima parte del homer (Ez 45:11, 14). El mar de bronce de Salomón contenía 2.000 batos (1 R 7:26; 2 Cr 4:5), y cada una de sus diez pilas contenía 40 batos (1 R 7:38). Isaías 5:10 advierte que diez acres de viña producirán apenas un bato — señal de juicio divino. El español ''batos'' y el francés ''bath'' conservan el término hebreo prácticamente sin cambios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1328a', 'spa', 'Betuel, sobrino de Abraham, hijo de Nacor, y padre de Rebeca y Labán.', 'Nombre propio (posiblemente ''hombre de Dios'', comparable a מְתוּאֵל) que designa al hijo de Nacor, hermano de Abraham, y padre de Rebeca. Betuel desempeña un papel fundamental aunque sorprendentemente pasivo en las narrativas patriarcales: se le identifica como padre de Rebeca cuando el siervo de Abraham busca esposa para Isaac (Gn 24:15, 24, 47, 50), pero es Labán quien lleva la palabra. Consistentemente se le llama ''Betuel el arameo de Padán-Aram'' (Gn 25:20; 28:2, 5). Las traducciones son uniformes: español ''Betuel'', francés ''Bethuel'', alemán ''Betuel''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1330', 'spa', 'Virgen, doncella — mujer joven soltera, con énfasis en la pureza sexual; también se usa figuradamente de ciudades y naciones.', 'Virgen, doncella — mujer joven soltera, con énfasis en la pureza sexual; también se usa figuradamente de ciudades y naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1331', 'spa', 'Virginidad — el estado de ser virgen, o las pruebas físicas que demuestran la virginidad de una novia. El sustantivo masculino plural בְּתוּלִים (betu', 'Virginidad — el estado de ser virgen, o las pruebas físicas que demuestran la virginidad de una novia. El sustantivo masculino plural בְּתוּלִים (betulim) designa el estado de virginidad o la evidencia física del mismo, empleado en contextos legales y sociales relativos a la pureza sexual de una mujer antes del matrimonio. Deuteronomio 22:14-20 ofrece el tratamiento más completo, donde un esposo puede impugnar la virginidad de su novia y los padres de ella deben presentar las «señales de virginidad» (betulim) ante los ancianos, probablemente la vestidura manchada de sangre de la noche de bodas. Levítico 21:13 exige que el sumo sacerdote se case con una mujer «en su virginidad». Jueces 11:37-38 relata cómo la hija de Jefté lamentó su virginidad en los montes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1335', 'spa', 'partes, mitades — trozos de animales cortados para los ritos de alianza', 'Este sustantivo designa las piezas o mitades de animales partidos en las ceremonias antiguas de pacto. En Génesis 15:10, Abraham corta los animales «por la mitad», y en Jeremías 34:18-19 se amenaza a los transgresores del pacto con la suerte del becerro entre cuyas partes pasaron. El rito consistía en dividir los animales en dos y caminar entre los trozos, invocando simbólicamente una maldición sobre quien quebrantara la alianza. La palabra podría aparecer también en Cantares 2:17 como «montes de Beter» (montes hendidos), aunque esto se discute.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1339', 'spa', 'Betsabé — ''hija de un juramento''; esposa de Urías el hitita, luego de David; madre de Salomón. El nombre בַּת־שֶׁבַע (''hija de un juramento'' o ''hija d', 'Betsabé — ''hija de un juramento''; esposa de Urías el hitita, luego de David; madre de Salomón. El nombre בַּת־שֶׁבַע (''hija de un juramento'' o ''hija de abundancia'') pertenece a una de las mujeres más decisivas en la historia real de Israel. Presentada primero como esposa de Urías el hitita (2 Sam 11:3), se convierte en el catalizador del gran pecado de David y su posterior arrepentimiento. Tras la muerte de su primer hijo, da a luz a Salomón (2 Sam 12:24) y más tarde asegura su sucesión presentándose con audacia ante el envejecido David (1 Re 1:11-31). Es la única mujer ante quien Salomón se levanta para saludar y a quien sienta a su diestra (1 Re 2:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1342', 'spa', 'Levantarse, crecer, ser ensalzado — de aguas que suben, plantas que crecen, o Dios triunfando gloriosamente', 'Verbo Qal (גָּאָה) que significa ''levantarse'' o ''ser ensalzado'', abarcando tanto fenómenos naturales como el triunfo divino. Su uso más célebre aparece en el Cántico del Mar: ''Cantaré al SEÑOR, porque ha triunfado gloriosamente'' (Éx 15:1, 21), donde la construcción de acusativo cognado גָּאֹה גָּאָה intensifica el verbo hasta convertirlo en un grito de victoria cósmica. En otros pasajes, el mismo verbo describe aguas que suben en el río del templo de Ezequiel (Ez 47:5) y juncos que crecen sin agua (Job 8:11), enraizando la exaltación divina en el mundo observable de lo que surge hacia lo alto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1343', 'spa', 'Soberbio, arrogante, altivo — describe a quienes se exaltan contra Dios u oprimen al humilde.', 'Adjetivo que designa a la persona soberbia o arrogante, usado en la literatura sapiencial y profética para describir a quienes se exaltan en desafío contra Dios. En Job 40:11-12, Dios mismo reta a Job a mirar a todo soberbio y humillarlo. Los Salmos 94:2 y 140:5 invocan la justicia divina contra los arrogantes, mientras que Proverbios 15:25 y 16:19 contrastan al soberbio con el humilde, a quien Dios favorece. Los términos en español ''soberbio'' y en francés orgueilleux subrayan el peso moral del vocablo: no se trata de mera confianza, sino de una autoexaltación culpable que invita la corrección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1346', 'spa', 'Soberbia, arrogancia u orgullo merecedor de juicio; también majestad, excelencia o grandeza digna atribuida a Dios. Pocas palabras hebreas ilustran la', 'Soberbia, arrogancia u orgullo merecedor de juicio; también majestad, excelencia o grandeza digna atribuida a Dios. Pocas palabras hebreas ilustran la ambigüedad moral de la ''grandeza'' de forma tan aguda. En la mayoría de sus apariciones, designa el orgullo pecaminoso de las naciones y los impíos — la arrogancia de Moab (Is 16:6), la altivez que precede a la caída (Pr 29:23). Sin embargo, el mismo sustantivo celebra la majestuosa cabalgata de Dios por los cielos (Dt 33:26) y la dignidad que Dios otorga a Israel (Dt 33:29). La diferencia no radica en la palabra misma sino en quién es exaltado: cuando Dios es la fuente, se convierte en gloria; cuando los humanos la toman para sí, se convierte en soberbia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1347', 'spa', 'Exaltación, majestad u orgullo; usado positivamente de la gloria divina y negativamente de la arrogancia y altivez humanas.', 'Exaltación, majestad u orgullo; usado positivamente de la gloria divina y negativamente de la arrogancia y altivez humanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1348', 'spa', 'Majestad, soberbia o elevación; el alzarse de la grandeza divina, la arrogancia humana o fenómenos físicos como el humo.', 'Derivado de la raíz ga''ah (''alzarse, ser exaltado''), este sustantivo capta el impulso ascendente de la exaltación en tres direcciones. Aplicado a Dios, es majestad gloriosa: YHWH está ''vestido de majestad'' (Sal 93:1), e Israel canta que ''ha hecho cosas magníficas'' (Is 12:5). Aplicado a los seres humanos, ese mismo alzarse se convierte en soberbia y arrogancia: la ''corona de soberbia de Efraín'' (Is 28:1, 3) y quienes ''hablan con arrogancia'' (Sal 17:10). En un uso físico singular, describe la columna de humo que asciende cuando la maldad arde como fuego (Is 9:18). La raíz compartida en los tres sentidos nos recuerda que majestad y soberbia son el mismo movimiento ascendente; la diferencia radica en quién se eleva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1350a', 'spa', 'Redimir o actuar como pariente; como participio: pariente redentor, Redentor divino o vengador de sangre', 'Pocas palabras hebreas portan tanta carga legal, familiar y teológica como גָּאַל. En su base se halla el deber del pariente más cercano (el גֹּאֵל) de rescatar la propiedad familiar, redimir a un pariente de la esclavitud o casarse con la viuda de un hermano fallecido — dramatizado vívidamente en el libro de Rut, donde Booz cumple este papel para la familia de Noemí. La misma raíz asciende hasta convertirse en uno de los grandes títulos divinos de la Escritura: Dios como Redentor de Israel, especialmente en Isaías 40-63, donde el éxodo de Babilonia se presenta como un nuevo acto de redención del גֹּאֵל. En un registro marcadamente distinto, el גֹּאֵל הַדָּם (''vengador de sangre'') de Números 35 persigue justicia por un pariente asesinado. El español se desdobla de manera similar — ''redimir'' para el sentido transaccional, ''Redentor'' para el título divino y ''vengador'' para el vengador de sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1351', 'spa', 'Contaminar, profanar o desecrar; quedar ritual o moralmente contaminado; manchar con sangre. Una raíz de contaminación que atraviesa todos los troncos', 'Contaminar, profanar o desecrar; quedar ritual o moralmente contaminado; manchar con sangre. Una raíz de contaminación que atraviesa todos los troncos del sistema verbal hebreo, cada uno aportando un matiz distinto de profanación. Sacerdotes con genealogías inciertas fueron ''desechados del sacerdocio como contaminados'' (Esd 2:62); Jerusalén misma es llamada ''la contaminada'' (Sof 3:1). Daniel resolvió no ''contaminarse'' con la comida del rey, y el Guerrero sufriente declara ''manché todos mis vestidos'' con la sangre del juicio (Is 63:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1353', 'spa', 'Redención, derecho de rescate — el acto legal o derecho de recuperar tierras, personas o propiedades', 'Sustantivo femenino derivado de la raíz גָּאַל (''redimir, actuar como pariente redentor''), que designa el acto, el derecho o el precio del rescate. Su ámbito principal es la legislación del Jubileo en Levítico 25, donde regula la recuperación de la tierra ancestral (v. 24), las casas en ciudades amuralladas (vv. 29–31), las propiedades levíticas (v. 32) y las personas vendidas como esclavas (vv. 48–52). El precio de redención (גְּאֻלָּתוֹ) se calcula en proporción a los años que faltan para el Jubileo. En Rut 4:6–7, el derecho de גְּאֻלָּה del pariente redentor se convierte en el eje narrativo cuando el pariente más cercano renuncia. Jeremías 32:7–8 invoca el מִשְׁפַּט הַגְּאֻלָּה (''derecho de rescate'') al comprar Jeremías el campo de su primo en Anatot — un acto simbólico de esperanza durante el asedio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1354', 'spa', 'Todo lo convexo o arqueado: la espalda, el aro de una rueda, un montículo cúltico, la protuberancia de un escudo o la ceja', 'Un sustantivo hebreo extraordinariamente versátil cuyo significado central es ''algo curvo o convexo''. Aparece en contextos sorprendentemente diversos — desde las espaldas de los labradores en el Salmo 129:3, hasta los aros de las ruedas de bronce de Salomón en 1 Reyes 7:33, pasando por los montículos de santuarios ilícitos que Ezequiel denuncia. Las traducciones al español revelan bien esta amplitud: ''espalda'' para la parte dorsal del cuerpo, ''aros'' para los aros de las ruedas y ''altar'' para los montículos cúlticos. La imagen subyacente es siempre una superficie arqueada y redondeada, ya sea anatómica, arquitectónica o mecánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1356a', 'spa', 'fosos, zanjas, cisternas — excavaciones para almacenar agua o con fines defensivos', 'Este sustantivo plural se refiere a depresiones excavadas en el suelo. En 2 Reyes 3:16, Eliseo ordena abrir «zanjas y más zanjas» para contener el agua milagrosa destinada a los ejércitos aliados. En Jeremías 14:3, y posiblemente 39:10, alude a cisternas, depósitos de agua esenciales para la agricultura antigua. La palabra deriva de raíces árabes y siríacas que significan «hueco» o «depresión». Existe cierta complejidad textual: algunos manuscritos de 2 Reyes 25:12 y Jeremías 52:16 podrían conservar este vocablo con el sentido de cisternas entregadas a los pobres, aunque el texto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1358', 'spa', 'Foso, cueva — sustantivo arameo para un recinto de animales, específicamente el foso de los leones en Daniel 6. El sustantivo arameo גֹּב (gob) design', 'Foso, cueva — sustantivo arameo para un recinto de animales, específicamente el foso de los leones en Daniel 6. El sustantivo arameo גֹּב (gob) designa un foso o cueva usado para confinar animales, apareciendo exclusivamente en Daniel 6, donde señala el célebre foso de los leones en el que Daniel fue arrojado. Las diez ocurrencias se concentran en este único capítulo, describiendo el foso con preposiciones de movimiento (''al foso'', ''del foso'') y en referencia absoluta (''el foso de los leones''). La palabra probablemente deriva de una raíz que significa ''cavar'' o ''ahuecar'', lo que sugiere un foso subterráneo más que una cueva natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1361', 'spa', 'Ser alto, exaltado; elevarse en altura, estatus u orgullo — abarcando desde la estatura física hasta la exaltación divina y la arrogancia humana', 'Ser alto, exaltado; elevarse en altura, estatus u orgullo — abarcando desde la estatura física hasta la exaltación divina y la arrogancia humana');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1362', 'spa', 'Alto, elevado, erguido; en sentido figurado, altivo o soberbio de corazón', 'Adjetivo que abarca tanto la altura física como la arrogancia moral. Describe personas altas (Saúl en 1 S 9:2), árboles imponentes (Ez 31:3), montes elevados y muros fortificados. Sin embargo, sus usos teológicamente más significativos son figurados: el ''altivo de corazón'' que el salmista no puede tolerar (Sal 101:5) y el ''de espíritu altanero'' contrastado con el paciente (Ec 7:8). Proverbios 16:5 declara que todo corazón soberbio es abominación para el SEÑOR, lo que convierte a este adjetivo en un término clave de la crítica sapiencial contra la soberbia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1363', 'spa', 'Altura física o estatura de edificios, árboles y personas; figuradamente, altivez, orgullo o dignidad exaltada. Sustantivo masculino de la raíz גבה (''', 'Altura física o estatura de edificios, árboles y personas; figuradamente, altivez, orgullo o dignidad exaltada. Sustantivo masculino de la raíz גבה (''ser alto, exaltado''), que abarca tanto la dimensión literal como la moral de lo elevado. En su sentido físico mide la altura de Goliat (1 S 17:4), el vestíbulo del templo (2 Cr 3:4), las estructuras visionarias de Ezequiel (Ez 1:18; 40:42; 41:8) y árboles imponentes (Ez 19:11; 31:10, 14; Am 2:9). Figuradamente describe la arrogancia de Moab (Jer 48:29), la altivez que precede a la caída (Pr 16:18), el orgullo de corazón (2 Cr 32:26), y también la dignidad majestuosa que Dios desafía a Job a vestir (Job 40:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1364', 'spa', 'Alto, elevado, encumbrado — adjetivo que describe altura física o exaltación figurativa y orgullo', 'Alto, elevado, encumbrado — adjetivo que describe altura física o exaltación figurativa y orgullo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1366', 'spa', 'Frontera, línea divisoria; por extensión, el territorio delimitado; raramente, el borde o reborde de un objeto.', 'Término geográfico fundamental del hebreo bíblico, esta palabra aparece con mayor frecuencia en las descripciones de límites tribales de Josué 15-19 y Números 34, trazando las líneas precisas donde una asignación tribal colinda con otra. Puede referirse tanto a la línea fronteriza misma (''la frontera salía hacia...'') como al territorio encerrado dentro de dichos límites (''tu territorio''). El español distingue ambos matices con claridad: frontera para la línea y territorio para el área. Un sentido ético especial emerge en Proverbios y Deuteronomio, donde mover el lindero del prójimo es condenado (Dt 19:14; Pr 22:28). En la visión del templo de Ezequiel, la palabra designa el reborde o cornisa del altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1367', 'spa', 'Frontera, límite — una línea fronteriza geográfica que marca los confines de un territorio o región. El sustantivo femenino גְּבוּלָה (gebulah) design', 'Frontera, límite — una línea fronteriza geográfica que marca los confines de un territorio o región. El sustantivo femenino גְּבוּלָה (gebulah) designa una frontera o línea limítrofe geográfica, usado en descripciones territoriales, declaraciones teológicas de soberanía divina y contextos morales de violación de límites. Aparece en las narraciones de reparto tribal (Nm 32:33; 34:2, 12; Jos 18:20; 19:49), donde delimita los confines precisos de la herencia de cada tribu. El Salmo 74:17 declara que Dios estableció todos los límites de la tierra, mientras que Deuteronomio 32:8 asigna las fronteras de los pueblos según el número de los hijos de Israel (o ''hijos de Dios''). Job 24:2 condena a quienes mueven los linderos — un acto de injusticia económica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1368', 'spa', 'Fuerte, poderoso; guerrero o valiente; como título divino: el Poderoso, el Dios fuerte.', 'Adjetivo de fuerza elemental que opera en tres registros distintos en la Biblia hebrea. Con mayor frecuencia designa al גִּבּוֹר: el guerrero, el valiente que pelea las batallas de Israel, desde Nimrod, ''vigoroso cazador'' (Gn 10:9), hasta los campeones de élite de David (2 S 23). Como atributo general describe a quien posee fuerza formidable: el león, ''el más fuerte entre las bestias'' (Pr 30:30). En su registro más elevado se convierte en epíteto divino: אֵל גִּבּוֹר, ''Dios fuerte'', título mesiánico de Isaías 9:6 y atributo del Dios que guarda el pacto (Dt 10:17; Neh 9:32). El cognado árabe جَبَّار abarca el mismo espectro, desde tirano hasta señor poderoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1369', 'spa', 'Fuerza, poder, poderío; valor heroico; hechos poderosos o actos de poder, especialmente de Dios o de guerreros.', 'Fuerza, poder, poderío; valor heroico; hechos poderosos o actos de poder, especialmente de Dios o de guerreros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1372', 'spa', 'Calvicie frontal, la parte delantera de la cabeza donde el cabello ha retrocedido; por extensión, el lado delantero de una prenda', 'Término técnico de las regulaciones levíticas de pureza que designa la zona frontal de la cabeza donde aparece la calvicie, a diferencia de la parte posterior (קָרַחַת). Las cuatro apariciones se encuentran en Levítico 13, donde los sacerdotes examinan erupciones cutáneas para determinar la pureza ritual. En Lv 13:42-43 el término se empareja con קָרַחַת (''calvicie posterior'') para delimitar las dos zonas del cuero cabelludo. En Lv 13:55 se extiende metafóricamente al ''lado delantero'' de una prenda, mostrando cómo la terminología corporal se aplicaba a la inspección de telas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1375', 'spa', 'Copa, tazón — vasija en forma de copa, ya sea el cáliz de adivinación de José o los ornamentos del candelabro', 'Sustantivo masculino que designa una vasija en forma de copa o tazón, presente en dos contextos narrativos muy diferentes que comparten, no obstante, la misma forma básica. En Génesis 44, גָּבִיעַ es la copa de plata de José — el cáliz que coloca secretamente en el costal de Benjamín y del que dice usarlo para la adivinación (Gn 44:2, 12, 16, 17). En Éxodo 25 y 37, la misma palabra describe las copas decorativas en forma de flor de almendro que adornan el candelabro de oro (menorá), donde tres copas con forma de flor de almendro ornamentan cada brazo (Éx 25:31–34; 37:17–20). Jeremías 35:5 completa el panorama con copas llenas de vino puestas ante los recabitas. El cognado árabe qub''ah (''copa'') y las traducciones interlingüísticas coincidentes (spa: copa, fra: coupe, deu: Kelch/Becher) confirman un núcleo semántico unificado centrado en la forma redondeada de la vasija.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1377', 'spa', 'gevirah — reina madre o dama noble; la madre del rey con autoridad en la corte', 'El sustantivo gevirah designa a una dama de alto rango, específicamente la reina madre: la madre del rey reinante que ostentaba autoridad política significativa en la monarquía judahíta. A diferencia de malkah («reina» como esposa del rey), gevirah señala la posición institucional única de la madre. En 1 Reyes 15:13 (= 2 Cr 15:16), Asá destituye a Maacá «de gevirah» —del cargo de reina madre— por su imagen idolátrica de Asera, revelando el título como un rol político revocable y no una mera etiqueta de parentesco. Jeremías se dirige al rey y a la gevirah como un par (Jer 13:18; 29:2), subrayando su lugar distintivo en la jerarquía real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1379', 'spa', 'Poner límites, establecer una frontera o marcar un lindero; usado para límites territoriales y perímetros sagrados.', 'Verbo denominativo derivado de גְּבוּל (''frontera''), que significa poner límites o establecer una línea divisoria. Su uso más dramático ocurre en el Sinaí, donde Dios ordena a Moisés poner límites alrededor del monte para que nadie lo toque (Éx 19:12, 23). En otros pasajes describe fronteras territoriales: el Jordán delimitando la herencia de Benjamín (Jos 18:20), los linderos ancestrales que no deben moverse (Dt 19:14) y la frontera de Hamat que alcanza hacia Sidón (Zac 9:2). El español capta bien este abanico semántico: desde ''pondrás límite'' en el Sinaí hasta ''delimitaba'' para las fronteras geográficas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1387', 'spa', 'Geba — una ciudad levítica en Benjamín cerca del paso de Micmas, que marca el límite norte de Judá. Geba es una ciudad levítica en el territorio triba', 'Geba — una ciudad levítica en Benjamín cerca del paso de Micmas, que marca el límite norte de Judá. Geba es una ciudad levítica en el territorio tribal de Benjamín, situada en el estratégico paso de Micmas al noreste de Jerusalén. El nombre probablemente deriva de la raíz g-b-'' que significa ''colina'', apropiado para un asentamiento encaramado en terreno elevado. Sus 18 apariciones abarcan textos de la conquista, la monarquía y el período postexílico. Josué 18:24 la incluye entre las ciudades asignadas a Benjamín, y Josué 21:17 la asigna a los levitas. La ciudad ganó fama militar cuando Jonatán atacó la guarnición filistea allí (1 S 13:3, 16; 14:5). La expresión formulaica ''desde Geba hasta Beerseba'' (2 R 23:8; Zac 14:10) define la extensión norte-sur del reino de Judá. Los exiliados que regresaron se reasentaron allí tras la cautividad babilónica (Esd 2:26; Neh 7:30; 11:31; 12:29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1389', 'spa', 'Colina o elevación de tierra; en plural, colinas; también el nombre propio Guibeá, una ciudad benjaminita.', 'Colina o elevación de tierra; en plural, colinas; también el nombre propio Guibeá, una ciudad benjaminita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1390', 'spa', 'Guibeá, ciudad de Benjamín; también Gueba (ciudad levítica distinta); raramente, ''colina'' como sustantivo común', 'Guibeá, ciudad de Benjamín; también Gueba (ciudad levítica distinta); raramente, ''colina'' como sustantivo común');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1391', 'spa', 'Gabaón — importante ciudad cananea que se convirtió en ciudad levítica en Benjamín, sede del tabernáculo y del famoso tratado', 'Gabaón — importante ciudad cananea que se convirtió en ciudad levítica en Benjamín, sede del tabernáculo y del famoso tratado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1393', 'spa', 'Gabaonita — habitante de Gabaón, la ciudad que hizo un pacto de paz con Israel.', 'Adjetivo gentilicio que identifica a un habitante de Gabaón, la ciudad hevea cuyos moradores engañaron famosamente a Josué para obtener un tratado de paz (Jos 9). En 2 Samuel 21:1-9, los gabaonitas exigen justicia por la violación de ese pacto por parte de Saúl, y David negocia con ellos; este pasaje concentra la mayoría de las ocho apariciones del término. En Nehemías 3:7 y 1 Crónicas 12:4, se mencionan gabaonitas individuales por nombre. El vocablo porta el peso de una relación de pacto que ni siquiera los reyes pueden anular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1396', 'spa', 'Ser fuerte, prevalecer, ser poderoso; fortalecer, confirmar; actuar con soberbia, enaltecerse', 'Ser fuerte, prevalecer, ser poderoso; fortalecer, confirmar; actuar con soberbia, enaltecerse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1397', 'spa', 'gever — un varón con énfasis en fuerza y vigor; hombre robusto o en edad guerrera, distinto de ish y adam.', 'gever — un varón con énfasis en fuerza y vigor; hombre robusto o en edad guerrera, distinto de ish y adam.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1400', 'spa', 'Hombre, varón (arameo); cognado arameo del hebreo «geber», que designa a un hombre individual o a hombres en sentido colectivo', 'Hombre, varón (arameo); cognado arameo del hebreo «geber», que designa a un hombre individual o a hombres en sentido colectivo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1404', 'spa', 'Señora, ama; mujer que ejerce autoridad sobre siervos o que ostenta soberanía regia', 'El equivalente femenino de gever/gibbor (''hombre fuerte''), designa a una mujer que posee autoridad. En su uso más frecuente, גְּבֶרֶת describe al ama de casa en relación con sus siervas: Sara sobre Agar es el caso paradigmático (Gn 16:4, 8, 9), y el Salmo 123:2 generaliza la relación: ''como los ojos de la sierva hacia la mano de su señora.'' En Isaías 47:5, 7 el término adquiere proporciones mayores, donde Babilonia es llamada irónicamente גְּבֶרֶת מַמְלָכוֹת (''señora de los reinos''), un título de soberanía imperial que Dios está a punto de arrebatarle.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1405', 'spa', 'Gibetón — ciudad levítica en el territorio de Dan, pueblo fronterizo disputado por los filisteos', 'Gibetón (que significa «montículo» o «altura») es una ciudad levítica en el territorio tribal de Dan, situada en la frontera disputada con los filisteos. Aparece en las listas de reparto (Jos 19:44) y en el registro de ciudades levíticas (Jos 21:23), y luego emerge dramáticamente en las narraciones de 1 Reyes 15-16, donde el ejército israelita la asedia dos veces: primero cuando Baasa asesina a Nadab (1 Re 15:27) y de nuevo cuando Zimri derroca a Elá (1 Re 16:15, 17). Su papel reiterado como sitio de asedio subraya cómo esta pequeña ciudad fronteriza se hallaba en la línea de fractura entre Israel y Filistea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1406', 'spa', 'Techo, azotea — la superficie plana superior de un edificio, usada para actividades cotidianas, refugio y proclamación', 'Techo, azotea — la superficie plana superior de un edificio, usada para actividades cotidianas, refugio y proclamación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1410', 'spa', 'Gad — ''fortuna''; séptimo hijo de Jacob por medio de Zilpa, la tribu que desciende de él, o el profeta que sirvió a David.', 'Gad — ''fortuna''; séptimo hijo de Jacob por medio de Zilpa, la tribu que desciende de él, o el profeta que sirvió a David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1413', 'spa', 'Cortarse, hacerse incisiones en duelo o ritos paganos; también reunirse en tropas, juntarse como banda hostil', 'Un verbo con dos caminos semánticos notablemente distintos. En su uso más común, describe la autolaceración ritual: cortarse o hacerse incisiones en el cuerpo como acto de duelo o culto pagano, práctica explícitamente prohibida en Deuteronomio 14:1 y dramáticamente ejecutada por los profetas de Baal en el monte Carmelo (1 R 18:28). El segundo sentido, ''reunirse en tropas'' o ''agruparse'', probablemente deriva del sustantivo relacionado גְּדוּד (''banda de asalto''), evocando una asamblea hostil. El cognado árabe jadda (''cortar'') ancla el sentido físico de corte, mientras que la metáfora militar de ''irrumpir'' en territorio enemigo conecta con el sentido de agrupación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1415', 'spa', 'Ribera, orilla del río; el borde o terraplén de un río, usado exclusivamente del Jordán y del Éufrates desbordándose.', 'Sustantivo femenino que significa ''ribera'' u ''orilla del río'', que aparece siempre en plural constructo con sufijo posesivo (''sus riberas''). Se emplea en contextos de ríos desbordados: el Jordán en época de crecida durante la cosecha (Jos 3:15; 4:18), los guerreros cruzando el Jordán cuando se desbordaba por todas sus orillas (1 Cr 12:16), y el Éufrates en la metáfora isaiana de la invasión asiria inundando ''por todas sus riberas'' (Is 8:7). El cognado árabe ǧuddah confirma el significado de ''borde, ribera''. En español, tanto ''riberas'' como ''orillas'' captan este sentido fluvial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1416', 'spa', 'Banda, tropa, partida de asalto — un destacamento de hombres organizados para la guerra o el saqueo', 'Banda, tropa, partida de asalto — un destacamento de hombres organizados para la guerra o el saqueo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1419a', 'spa', 'Grande; de tamaño, importancia, rango o edad; sustantivado como ''grandes/nobles'' o ''grandes obras/prodigios''.', 'גָּדוֹל es el adjetivo primario del hebreo para la grandeza en todas sus dimensiones: tamaño físico, importancia social, intensidad emocional y peso moral. Una gran ciudad, una gran nación, un gran Dios: la palabra se extiende sin esfuerzo entre lo concreto y lo abstracto. Sustantivado en masculino plural designa ''grandes'' o ''nobles'', y en femenino plural ''grandes cosas'' o ''prodigios''. También funciona como comparativo para ''mayor'' en contextos de primogenitura, y ocasionalmente aparece en construcciones verbal-progresivas con el sentido de ''ir en aumento''. Su altísima frecuencia (527 apariciones) lo convierte en pieza angular del vocabulario descriptivo hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1420', 'spa', 'Grandeza, magnificencia; de la majestad o las obras poderosas de Dios, y del honor o rango humano', 'Sustantivo que denota grandeza, ya sea la majestad intrínseca de Dios o el honor y la dignidad de un gobernante humano. David alaba la grandeza de Dios junto con la soberanía, el poder, la gloria y el esplendor (1 Cr 29:11), y el salmista declara que su grandeza es insondable (Sal 145:3, 6). La misma palabra describe el ascenso de Mardoqueo en la corte persa (Est 6:3; 10:2) y el esplendor del rey Asuero (Est 1:4). En 2 Samuel 7:21, 23 y 1 Crónicas 17:19, 21 se refiere concretamente a las grandes obras que Dios ha hecho por Israel. El plural intensifica el significado hacia ''grandes hazañas'' u ''obras poderosas''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1421', 'spa', 'ultrajes, injurias — palabras de escarnio y abuso contra personas o contra Dios', 'Este sustantivo masculino plural denota palabras injuriosas, insultos o abuso verbal. Aparece tres veces en contextos proféticos, siempre emparejado con términos afines de oprobio (חֶרְפָּה, «afrenta»). Isaías lo emplea tanto para insultos entre personas (43:28) como para el escarnio contra el pueblo de Dios que no deben temer (51:7). Sofonías 2:8 lo aplica a las burlas de Moab contra Judá. La raíz sugiere un discurso blasfemo o despectivo que deshonra a su destinatario. Es más fuerte que una simple crítica: implica un lenguaje activamente despreciativo y degradante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1423', 'spa', 'Cabrito — una cría de cabra, frecuentemente especificado como ''cabrito de las cabras''; usado en sacrificios, alimentación y vida pastoral. El término ', 'Cabrito — una cría de cabra, frecuentemente especificado como ''cabrito de las cabras''; usado en sacrificios, alimentación y vida pastoral. El término hebreo estándar para una cría de cabra, que casi siempre aparece en la frase más completa גְּדִי עִזִּים (''cabrito de las cabras''). Figura en tres de las escenas más memorables de la Biblia: Rebeca disfraza a Jacob con pieles de cabritos para engañar a Isaac (Gn 27:9, 16), Judá promete un cabrito como pago a Tamar (Gn 38:17-23), y la triple ley dietética prohíbe cocer el cabrito en la leche de su madre (Éx 23:19; 34:26; Dt 14:21). El cabrito también sirve como ofrenda sacrificial (Jue 6:19; 13:15, 19) y como regalo (1 S 16:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1425', 'spa', 'Gadita — un miembro de la tribu israelita de Gad, usado como adjetivo gentilicio y sustantivo colectivo. El adjetivo gentilicio derivado de Gad, que d', 'Gadita — un miembro de la tribu israelita de Gad, usado como adjetivo gentilicio y sustantivo colectivo. El adjetivo gentilicio derivado de Gad, que designa a individuos o al cuerpo colectivo de la tribu de Gad. Esta tribu recibió su heredad en Transjordania — el territorio al este del río Jordán — junto con los rubenitas y la media tribu de Manasés (Dt 3:12, 16; Jos 13:8). Los gaditas eran conocidos como guerreros capaces: 1 Crónicas 12:8 los describe como hombres cuyos rostros eran como de leones y veloces como gacelas. Aparecen en listas militares y administrativas (1 Cr 5:18, 26; 12:37; 26:32; 2 R 10:33) y en la narrativa del pacto de Deuteronomio 29:7.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1428', 'spa', 'ribera de un río; el borde desbordante u orilla de un cauce en época de crecida', 'Este término describe las riberas de un río cuando están a punto de desbordarse, especialmente durante la temporada de crecidas. El Jordán desbordaba sus riberas en tiempo de cosecha cuando Israel lo cruzó milagrosamente, lo cual subraya la trascendencia del momento elegido. Crónicas e Isaías emplean la imagen de aguas que alcanzan las riberas para ilustrar abundancia o amenaza de inundación. La palabra no designa simplemente el borde del río, sino el instante dramático de plenitud, cuando el agua llega al límite mismo de su cauce. Esta imagen de desbordamiento se convirtió en una poderosa metáfora de la acción divina o militar avasalladora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1430a', 'spa', 'parva, gavilla — montón de grano cosechado y apilado en el campo', 'Este sustantivo designa un montón o pila de grano cosechado, concretamente gavillas agrupadas en el campo. Aparece en contextos agrícolas y legales: Éxodo 22:6 trata las leyes contra el incendio de parvas, Jueces 15:5 describe cómo Sansón quemó las parvas de los filisteos, y Job 5:26 lo usa metafóricamente para referirse a llegar a la tumba «en pleno vigor», literalmente «como gavilla recogida a su tiempo». La palabra subraya la naturaleza agrupada y abundante de la cosecha — no tallos individuales, sino la riqueza reunida de la mies.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1431', 'spa', 'Crecer, hacerse grande; en Piel magnificar, criar; en Hifil engrandecer, hacer proezas; reflexivamente jactarse.', 'Verbo hebreo versátil que abarca todo el arco de la grandeza, desde el crecimiento físico de un niño hasta la magnificación soberana que Dios hace de sus siervos. En Qal describe tanto el proceso orgánico de crecer (Gn 21:8) como el estado de ser grande (2 S 7:22). El Piel intensifica esto en actos deliberados de exaltar o criar, como cuando Dios declara ''crié hijos'' (Is 1:2). El Hifil capta la dimensión causativa --hacer grandes cosas o engrandecer a alguien--, mientras que el Hitpael reflexivo suele conllevar un tono más oscuro de autoglorificación y jactancia (Sal 55:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1432', 'spa', 'Que va creciendo, que se engrandece; participio activo qal que indica proceso de volverse grande o poderoso', 'Participio activo qal de גָּדַל (''ser grande'') que capta el proceso dinámico de crecer o engrandecerse. En Génesis 26:13 describe la prosperidad creciente de Isaac — ''iba engrandeciéndose'' hasta llegar a ser muy rico. En 1 Samuel 2:26 el joven Samuel ''seguía creciendo'' en estatura y en gracia, frase que luego se hace eco de Jesús en Lucas 2:52. En 2 Crónicas 17:12 Josafat ''se engrandeció cada vez más''. El único uso no progresivo aparece en Ezequiel 16:26, donde la expresión ''grandes de carne'' porta una connotación más física e incluso cruda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1433', 'spa', 'Grandeza, magnitud; del poder de Dios, la majestad de un rey o (negativamente) la arrogancia del corazón.', 'Sustantivo que expresa grandeza en escala, poder o dignidad. Moisés invoca repetidamente la grandeza de Dios —su brazo, su misericordia, su majestad— al suplicar ante el SEÑOR (Nm 14:19; Dt 3:24; 5:24; 9:26; 11:2; 32:3). Ezequiel lo emplea para describir un cedro imponente que simboliza la magnificencia real (Ez 31:2, 7, 18). Pero la palabra también tiene un matiz sombrío: Isaías la usa dos veces para la ''grandeza de corazón'' que en realidad es arrogancia e insolencia (Is 9:8; 10:12). El término abarca todo el espectro, desde la majestad divina hasta la soberbia humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1435', 'spa', 'Guidel, nombre propio que significa ''muy grande''; llevado por dos cabezas de familias de siervos postexílicos', 'Nombre propio derivado del verbo גָּדַל (''engrandecer''), que significa ''él ha engrandecido'' o ''muy grande''. Identifica a dos individuos distintos en las listas censales postexílicas. El primer Guidel encabeza una familia entre los netineos (sirvientes del templo) en Esdras 2:47 y Nehemías 7:49. El segundo encabeza una familia entre los siervos de Salomón en Esdras 2:56 y Nehemías 7:58. Las listas paralelas de Esdras y Nehemías confirman que ambas familias regresaron del exilio babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1436a', 'spa', 'Gedalías — ''Yah es grande''; nombre propio del gobernador de Judá y de varios otros hombres bíblicos', 'Gedalías (que significa ''YHWH es grande'') es un nombre propio que llevan varios personajes en la Biblia hebrea. El más destacado es Gedalías hijo de Ahicam, a quien Nabucodonosor nombró gobernador de Judá tras la destrucción de Jerusalén en 586 a.C. (Jer 40-41). Su breve gobierno y posterior asesinato a manos de Ismael hijo de Netanías provocaron la huida del remanente a Egipto, y se conmemoran en el ayuno judío de Tzom Gedaliah. Otros portadores del nombre incluyen un antepasado de Sofonías (Sof 1:1) y un sacerdote de la línea de Jesúa que se había casado con una mujer extranjera (Esd 10:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1436b', 'spa', 'Gedalyahu — nombre propio que significa «Yah(u) es grande», llevado por el gobernador de Judá y otras figuras bíblicas', 'Gedalyahu — nombre propio que significa «Yah(u) es grande», llevado por el gobernador de Judá y otras figuras bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1438', 'spa', 'Talar, cortar, derribar (Qal/Piel activo); ser talado, ser cortado (Nifal pasivo)', 'Talar, cortar, derribar (Qal/Piel activo); ser talado, ser cortado (Nifal pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1439', 'spa', 'Gedeón — juez israelita de Manasés que derrotó a Madián con 300 hombres por mandato divino (Jueces 6-8)', 'Gedeón — juez israelita de Manasés que derrotó a Madián con 300 hombres por mandato divino (Jueces 6-8)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1441', 'spa', 'Gedeoni; benjamita, padre de Abidán, quien sirvió como príncipe de la tribu de Benjamín durante la peregrinación en el desierto.', 'Nombre propio masculino que significa algo como ''mi talador'' o ''guerrero'', portado por un benjamita cuyo hijo Abidán sirvió como príncipe designado de Benjamín durante el censo y la organización del campamento en el desierto. Cada ocurrencia sigue la fórmula patronímica fija ''Abidán hijo de Gedeoni'' (Nm 1:11; 2:22; 7:60, 65; 10:24). El nombre se mantiene notablemente consistente en las traducciones: ''Gedeoni'' en español, francés y alemán, reflejando su transliteración transparente. Aparece solo en las listas tribales formulaicas de Números, siempre vinculado al papel de liderazgo de su hijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1442', 'spa', 'Blasfemar, injuriar — hablar con desprecio contra Dios o ultrajar a otros (solo en Piel)', 'Verbo usado exclusivamente en la conjugación Piel (גִּדֵּף), que significa injuriar o blasfemar: hablar con un desprecio hiriente, ya sea contra Dios o contra personas. El cognado árabe جَدَفَ (''cortar, cercenar'') revela el origen metafórico: la blasfemia como violencia verbal que corta el vínculo de reverencia. En Números 15:30, quien actúa ''con mano alzada'' blasfema contra el SEÑOR y es extirpado de Israel. En 2 Reyes 19:22 (= Is 37:23), Ezequías cita a Dios reprendiendo a Senaquerib: ''¿A quién has injuriado y blasfemado?''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1443', 'spa', 'Construir un muro; encerrar con muros o bloquear un camino; reparar una brecha — el ciclo completo de las delimitaciones de piedra. Un verbo hebreo ar', 'Construir un muro; encerrar con muros o bloquear un camino; reparar una brecha — el ciclo completo de las delimitaciones de piedra. Un verbo hebreo arraigado en el mundo físico de la piedra y el mortero. En su uso más literal, describe el trabajo de albañiles — los ''constructores de muros'' que reparaban el Templo (2 Re 12:13; 22:6). Dios, sin embargo, usa los muros figuradamente: ''cerca'' el camino de Job para que no pueda pasar (Job 19:8) y cerca el camino de Gomer con espinos (Os 2:6). El mismo verbo también describe la reparación de lo roto — el ''reparador de portillos'' en Isaías 58:12 y la restauración de la cabaña caída de David en Amós 9:11.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1446', 'spa', 'Gedor — ciudad en la serranía de Judá y nombre propio en las genealogías benjaminitas y judaítas', 'Nombre propio (גְּדוֹר / גְּדֹר) relacionado con el árabe جِدَارٌ (''muro''), lo que sugiere un asentamiento amurallado. Designa tanto un lugar como personas. Como ciudad, Gedor aparece entre las localidades de la serranía de Judá (Jos 15:58). En las genealogías del Cronista, Gedor figura como ''hijo'' de Penuel (1 Cr 4:4) y de Jered (1 Cr 4:18), probablemente fundadores epónimos de la ciudad. Un benjaminita llamado Gedor de Gabaón también aparece (1 Cr 8:31; 9:37). En 1 Crónicas 4:39 el texto lee Gedor, aunque muchos estudiosos enmiendan a Gerar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1447', 'spa', 'Muro, cerca, recinto de piedra — barrera delimitadora alrededor de viñedos, campos o asentamientos', 'Muro, cerca, recinto de piedra — barrera delimitadora alrededor de viñedos, campos o asentamientos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1448', 'spa', 'Muro, cerca, seto; redil o corral para ganado; también nombre propio (Gederá), ciudad en Judá', 'Muro, cerca, seto; redil o corral para ganado; también nombre propio (Gederá), ciudad en Judá');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1457', 'spa', 'agacharse, inclinarse, tenderse — postura corporal de intercesión profética o resurrección', 'Este verbo poco frecuente describe la postura física de agacharse o tenderse sobre algo. Elías se inclinó hasta el suelo con el rostro entre las rodillas mientras oraba por lluvia (1 R 18:42). Eliseo se tendió sobre el hijo muerto de la sunamita, dos veces, en el acto de resucitarlo (2 R 4:34-35). El verbo transmite un intenso compromiso físico en la intercesión profética o en la obra milagrosa. Sugiere algo más que un simple inclinarse: una postura deliberada y concentrada de labor espiritual, ya sea en oración ferviente o en ministerio de resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1458', 'spa', 'la espalda — la espalda humana, usada figuradamente para el rechazo y el desprecio deliberado', 'Este sustantivo que designa la espalda humana aparece únicamente en la expresión ''echar tras la espalda'', una vívida metáfora de rechazo y desdén deliberado. En 1 Reyes 14:9, Jeroboam echó a Dios mismo tras su espalda. En Ezequiel 23:35, Jerusalén echó a Dios tras su espalda. En Nehemías 9:26, el Israel rebelde echó la ley de Dios tras sus espaldas. La imagen es poderosa: darle la espalda a alguien, sacarlo de la vista y de la mente, tratarlo como irrelevante u olvidado. Es la expresión física del abandono espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1459', 'spa', 'Sustantivo arameo para ''medio, interior''; usado preposicionalmente (con b-, l-, min-) para expresar ubicación dentro o movimiento hacia.', 'Sustantivo arameo que significa ''medio'' o ''interior'', que aparece exclusivamente en Daniel y Esdras. Nunca se usa de forma independiente, sino siempre combinado con una preposición: b-go (''en medio de''), l-go (''hacia dentro'') o min-go (''fuera de''). La narración del horno de fuego en Daniel 3 concentra la mayoría de las apariciones, donde la frase b-go nura (''en medio del fuego'') se convierte en un estribillo recurrente. La forma cognada aparece en siríaco y arameo nabateo, señalando un término espacial común del arameo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1460a', 'spa', 'gev — la espalda (de una persona); la parte del cuerpo que recibe golpes o cargas', 'El sustantivo gev designa la espalda humana, es decir, la parte dorsal del cuerpo. En Proverbios aparece tres veces en la fórmula proverbial ''vara para la espalda del necio'' (Prov 10:13; 19:29; 26:3), donde la espalda es el blanco del castigo disciplinario. Isaías 50:6 lo emplea en el Cántico del Siervo: ''Di mi espalda a los que me golpeaban'', describiendo la sumisión voluntaria al sufrimiento. Un uso figurado notable se halla en Isaías 38:17, donde Ezequías dice que Dios ha echado todos sus pecados ''detrás de tu espalda'', es decir, fuera de su vista y memoria. Isaías 51:23 describe a los conquistadores convirtiendo las espaldas de los sometidos en camino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1463', 'spa', 'Gog — nombre propio: (1) un rubenita en 1 Crónicas; (2) el enemigo escatológico de Magog en Ezequiel 38-39', 'Gog — nombre propio: (1) un rubenita en 1 Crónicas; (2) el enemigo escatológico de Magog en Ezequiel 38-39');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1464', 'spa', 'asaltar, atacar, invadir — incursión o asalto militar', 'Este verbo describe una incursión o ataque militar. Aparece de forma destacada en Génesis 49:19, en la bendición de Jacob sobre Gad, con un juego de palabras sobre el nombre tribal: ''Gad, una tropa lo asaltará, pero él asaltará su retaguardia''. La aliteración en hebreo (גָּד גְּדוּד יְגוּדֶנּוּ וְהוּא יָגֻד עָקֵב) es notable. En Habacuc 3:16 se refiere a un enemigo que nos atacará. El verbo posiblemente deriva de גְּדוּד (''banda de asaltantes''), lo cual sugiere la acción de una partida de incursión: un asalto rápido y agresivo, no un asedio formal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1466', 'spa', 'soberbia, exaltación — autoexaltación arrogante o exclamación de ''¡arriba!''', 'Este sustantivo femenino, forma contraída de גַּאֲוָה, significa soberbia o exaltación. En Job 33:17, Dios actúa para apartar al ser humano de sus obras y ocultar la soberbia. En Jeremías 13:17, el alma del profeta llora por la soberbia del pueblo. Job 22:29 es discutido: podría ser una exclamación ''¡Arriba!'' (exhortando a levantarse) o bien referirse a la soberbia que Dios humillará. La palabra deriva de raíces que expresan elevación y exaltación, con connotaciones tanto neutras (levantamiento) como negativas (orgullo arrogante), según el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1470', 'spa', 'Gozán; ciudad y distrito en Mesopotamia sobre el río Habor, destino de los israelitas deportados por Asiria.', 'Topónimo que designa una ciudad y región en la alta Mesopotamia, correspondiente a la asiria Guzana, situada junto al río Habor (actual Tell Halaf, en el noreste de Siria). Aparece en dos contextos históricos: como destino de los deportados israelitas tras la caída de Samaria en 722 a.C. (2 Re 17:6; 18:11; 1 Cr 5:26), y entre las naciones cuyos dioses no pudieron salvarlas de Asiria, citada como advertencia a Jerusalén (2 Re 19:12 = Is 37:12). La transliteración es uniforme en todas las traducciones principales: inglés, español, francés y alemán coinciden en ''Gozán''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1471a', 'spa', 'Nación, pueblo; en plural frecuentemente ''las naciones'' (pueblos no israelitas, gentiles).', 'El hebreo גּוֹי designa una nación o pueblo entendido como unidad política y étnica. En singular puede referirse a cualquier nación, incluido el propio Israel: Dios promete a Abraham ''haré de ti una gran nación'' (Gn 12:2). Pero en plural, גּוֹיִם designa abrumadoramente ''las naciones'', es decir, los pueblos extranjeros circundantes, y con el tiempo se convierte en casi sinónimo de ''gentiles''. El alemán distingue Völker (pueblos) de Nationen (estados-nación); el árabe emplea أُمَم (comunidades) para el colectivo plural. El cognado fenicio גו (''comunidad'') conserva el sentido raíz de un cuerpo social delimitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1472', 'spa', 'Cuerpo (vivo o muerto); cadáver — de seres humanos en vida, muerte o imaginería visionaria.', 'Sustantivo femenino que designa el cuerpo físico, ya sea vivo o muerto. En Génesis 47:18, los israelitas ofrecen sus cuerpos (geviyyotenu) al faraón cuando el hambre agota todos los demás recursos — un cuerpo vivo entregado por desesperación. En 1 Samuel 31:10-12, la misma palabra nombra los cadáveres de Saúl y sus hijos colgados en el muro de Bet-sán. Las criaturas vivientes de Ezequiel tienen geviyyot como estructura corporal (Ez 1:11, 23), mientras que Daniel ve una figura cuya geviyyah brilla como berilo (Dn 10:6). El término abarca todo el arco desde la carne que respira hasta los restos del campo de batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1473', 'spa', 'Exilio, cautiverio; colectivamente la comunidad de exiliados, especialmente los deportados a Babilonia', 'Exilio, cautiverio; colectivamente la comunidad de exiliados, especialmente los deportados a Babilonia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1474', 'spa', 'Golán — ciudad levítica de refugio en Basán, en el territorio de Manasés oriental', 'Golán es el nombre propio de una ciudad en Basán designada como una de las seis ciudades de refugio (tres a cada lado del Jordán). Situada en el territorio de Manasés oriental, fue asignada al clan levítico de Gersón (1 Cr 6:71). Moisés mismo la apartó como ciudad de refugio para el homicida involuntario (Dt 4:43), y reaparece en las listas formales de Josué tanto de ciudades de refugio (Jos 20:8) como de ciudades levíticas (Jos 21:27). La variante Ketiv/Qere galon/golan refleja una cuestión ortográfica escribal, no una diferencia semántica. La moderna región de los Altos del Golán deriva su nombre de esta antigua ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1476', 'spa', 'Guni, nombre propio de un hijo de Neftalí y ancestro del clan gunita, y de un gadita en las genealogías', 'Nombre propio de etimología incierta, portado por al menos dos personajes del Antiguo Testamento. El Guni principal es hijo de Neftalí, mencionado entre quienes descendieron a Egipto con Jacob (Gn 46:24), y se convierte en el ancestro epónimo del clan gunita registrado en el censo del desierto (Nm 26:48). Un segundo Guni aparece en la genealogía gadita de 1 Crónicas 5:15. El nombre reaparece en 1 Crónicas 7:13 dentro de la genealogía neftalita, confirmando el linaje tribal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1478', 'spa', 'Expirar, exhalar el último aliento, perecer — morir, especialmente dicho de los patriarcas; enfatiza el momento en que la vida se va', 'Expirar, exhalar el último aliento, perecer — morir, especialmente dicho de los patriarcas; enfatiza el momento en que la vida se va');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1481a', 'spa', 'Peregrinar como residente extranjero; habitar temporalmente en tierra ajena; como participio, un forastero o huésped.', 'Peregrinar como residente extranjero; habitar temporalmente en tierra ajena; como participio, un forastero o huésped.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1481b', 'spa', 'Provocar contienda, atacar, asaltar; en Hitpael, lacerarse — acción hostil que va del conflicto a la automutilación ritual', 'Este es gur II, distinto del mucho más frecuente gur I (''residir como extranjero''). Mientras gur I transmite residencia pacífica, gur II porta connotaciones agresivas: provocar contienda, congregarse con hostilidad o lanzar ataques. Los Salmos lo emplean en contextos de lamento — los enemigos acechan y asaltan (Sal 56:6; 59:3; 140:2) — mientras que Isaías 54:15 usa tanto el infinitivo absoluto como el imperfecto para dar énfasis: ''el que conspire contra ti caerá.'' Una única aparición en Hitpael en Oseas 7:14, yitgoraru (''se laceran''), describe rituales paganos de duelo con automutilación, posiblemente vinculada a la raíz relacionada garar o garah.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1481c', 'spa', 'Temer, tener miedo, sentir reverencia — homógrafo de gur I (peregrinar) y gur II (provocar contienda)', 'Temer, tener miedo, sentir reverencia — homógrafo de gur I (peregrinar) y gur II (provocar contienda)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1482', 'spa', 'Cachorro, cría de león; usado metafóricamente para el vigor tribal, guerreros jóvenes y descendencia feroz', 'Sustantivo masculino (גּוּר) que significa ''cachorro'' o ''cría'', principalmente referido a un león joven. Jacob bendice a Judá como ''cachorro de león'' (גּוּר אַרְיֵה, Gn 49:9), y Dan es llamado ''cachorro de león que salta desde Basán'' (Dt 33:22), evocando ferocidad juvenil y promesa tribal. La alegoría de Ezequiel sobre la leona (Ez 19:2, 3, 5) emplea el término para los príncipes de Israel criados entre sus cachorros. En Lamentaciones 4:3 se extiende más allá de los leones para describir las crías de los chacales (תַּנִּין), mostrando que la palabra puede designar cualquier cría de depredador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1486', 'spa', 'Suerte, sorteo — un objeto pequeño echado para decisiones divinas; por extensión, la porción o destino así asignado.', 'Suerte, sorteo — un objeto pequeño echado para decisiones divinas; por extensión, la porción o destino así asignado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1488', 'spa', 'Esquileo, vellón; siega, hierba cortada — lo que se corta de las ovejas o del campo', 'Designa el producto de cortar, ya sea la lana esquilada de los animales o la hierba segada de un campo. En Deuteronomio 18:4 las «primicias del esquileo de tus ovejas» figuran entre las porciones debidas a los levitas. Job 31:20 invoca el vellón de sus propias ovejas como prueba de su generosidad hacia los pobres. El Salmo 72:6 emplea la imagen de la lluvia cayendo sobre la hierba recién segada para retratar el reinado suave y vivificante del rey ideal. Amós 7:1 menciona «la siega del rey» — un primer corte real de heno — como escenario de una visión de plaga de langostas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1492', 'spa', 'Vellón; la lana esquilada de una oveja, usado exclusivamente en el relato de Gedeón como señal divina', 'Vellón de lana, referido al grueso manto esquilado de una oveja. Todas las apariciones en la Biblia hebrea se encuentran en el célebre relato de la prueba de Gedeón ante Dios (Jue 6:37-40), donde extendió un vellón en la era y pidió rocío como confirmación de la guía divina. El hebreo גִּזָּה es cognado del árabe jizzah y del arameo gezzta, apuntando todos a una raíz semítica común para la lana esquilada. Su uso escritural tan específico ha convertido la expresión ''poner un vellón'' en un dicho proverbial para buscar una señal de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1494', 'spa', 'Esquilar (ovejas), cortar (cabello) — trasquilar lana o cortar pelo, frecuentemente en ocasión festiva.', 'Gazaz describe el acto de esquilar ovejas o cortar cabello — en el mundo bíblico, eventos de importancia económica y social. La esquila era festiva: Labán estaba esquilando cuando Raquel robó los terafines (Gn 31:19), Judá subió a sus esquiladores en Timna (Gn 38:12-13), y la fiesta de esquila de Nabal fue el escenario de su enfrentamiento con David (1 S 25:2-11). Absalón aprovechó una reunión de esquila para asesinar a Amnón (2 S 13:23-24). De manera especialmente conmovedora, el siervo sufriente enmudece ante sus trasquiladores (Is 53:7). El verbo también se aplica al corte de cabello en señal de duelo (Job 1:20; Jer 7:29; Mi 1:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1496', 'spa', 'Piedra labrada, sillería — bloques cortados y escuadrados para construcción monumental', 'Piedra labrada, sillería — bloques cortados y escuadrados para construcción monumental');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1497', 'spa', 'Arrebatar, robar, quitar por la fuerza; despojar de bienes, ganado o personas mediante despojo violento', 'Arrebatar, robar, quitar por la fuerza; despojar de bienes, ganado o personas mediante despojo violento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1498', 'spa', 'Robo, saqueo; el acto de apoderarse de bienes por la fuerza, o lo arrebatado violentamente', 'Designa la apropiación violenta de las posesiones ajenas, tanto como acto abstracto como en referencia concreta a los bienes tomados. En Levítico 5:21 aparece junto al fraude y la extorsión en una lista de delitos que requieren restitución, mientras que el Salmo 62:10 lo empareja con la opresión (עֹשֶׁק) para advertir contra la confianza en ganancias ilícitas. Isaías 61:8 revela el aborrecimiento divino del robo, y Ezequiel 22:29 emplea la construcción de acusativo cognado (גָּזַל גָּזֵל) para subrayar cuán generalizado era el saqueo en Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1500', 'spa', 'gezelah — robo, despojo; el acto de apoderamiento violento o los bienes así tomados', 'El sustantivo femenino gezelah designa el robo o despojo, abarcando tanto el acto violento de apoderarse de los bienes ajenos como los bienes mismos así tomados. Derivado de la raíz g-z-l (''arrancar, arrebatar''), conlleva una fuerte connotación de apropiación forzosa e injusta. En Levítico 6:4 (TM 5:23) aparece en la ley de restitución: el ladrón debe devolver lo robado añadiendo una quinta parte de su valor. Ezequiel emplea el término tres veces (18:7, 12, 16) para distinguir al justo del malvado según si cometen robo. Isaías 3:14 acusa a los ancianos y príncipes de que ''el despojo del pobre está en vuestras casas'', haciendo de gezelah una denuncia de injusticia social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1501', 'spa', 'la langosta cortadora — especie de langosta en enjambres devastadores', 'Este sustantivo colectivo se refiere a una especie o etapa particular de langosta conocida por su acción de cortar y devorar. Siempre aparece en contextos de devastación agrícola. Joel 1:4 la enumera entre cuatro tipos de langosta (אַרְבֶּה, יֶלֶק, חָסִיל, גָּזָם) en una secuencia de plaga. Joel 2:25 promete la restauración de lo que la langosta cortadora consumió. Amós 4:9 describe a esta langosta devorando huertos, viñedos, higueras y olivos. El nombre probablemente deriva de una raíz que significa ''cortar'' o ''trasquilar'', enfatizando su capacidad destructiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1503', 'spa', 'tronco, cepa — el tronco o tocón de un árbol, especialmente después de ser cortado', 'Este sustantivo designa el tronco, la cepa o el tocón de un árbol, frecuentemente emparejado con «raíz» para subrayar la continuidad de la vida. Job 14:8 habla con esperanza de un tocón que rebrota. Isaías 11:1 profetiza célebremente un vástago que sale «del tronco de Jesé», el Mesías surgiendo de la dinastía menguada de David. Isaías 40:24 lo usa para plantas que apenas echan raíz antes de ser arrasadas. La palabra enfatiza lo que permanece tras la tala o el tronco fundacional del cual brota nueva vida, portando tanto realidad agrícola como poderoso simbolismo mesiánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1504', 'spa', 'Cortar, dividir o separar físicamente; por extensión, decretar o determinar (como ''cortar'' una decisión).', 'Verbo enraizado en el acto concreto de cortar o dividir algo en dos, como cuando Salomón ordenó dividir a un niño (1 R 3:25) o cuando el salmista recuerda a Dios partiendo el mar Rojo en secciones (Sal 136:13). El Nifal expresa ser cortado o excluido, transmitiendo un sentido de aislamiento o destrucción. En un uso posterior influido por el arameo, la palabra se extiende metafóricamente a decretar o determinar, como si una decisión fuera ''cortada'' para existir (Job 22:28). En español, ''dividió'' y ''cortará'' capturan la división física, mientras que ''decretarás'' marca la extensión jurídica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1505', 'spa', 'cortar, determinar; (participio) astrólogo/adivino que ''corta'' los cielos; (Hitpael) ser cortado, tallado', 'Verbo arameo cuyos dos sentidos se dividen claramente entre personas y cosas. Como participio sustantivado, designa a astrólogos o adivinos, aquellos que ''cortan'' o ''dividen'' los cielos para determinar el destino, y aparecen junto a magos y encantadores en la corte babilónica (Dan 2:27; 4:7; 5:7, 11). En la conjugación Hitpael (reflexiva/pasiva), el verbo describe una piedra que es ''cortada'' sin intervención humana en el sueño de Nabucodonosor (Dan 2:34, 45). El cognado árabe jazzar (''carnicero'') conserva la fuerza física de corte propia de esta raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1507', 'spa', 'Gezer — ciudad cananea fortificada en la frontera de Efraín y Judá, posteriormente ciudad levítica israelita.', 'Gezer fue una ciudad cananea estratégicamente vital, ubicada en el límite entre la Sefela costera y la región montañosa de Efraín. Su rey cayó ante Josué en Laquis (Jos 10:33), pero Israel no pudo expulsar completamente a sus habitantes cananeos durante siglos (Jos 16:10; Jue 1:29). El faraón finalmente conquistó e incendió la ciudad, entregándola como dote a la esposa egipcia de Salomón (1 R 9:16-17). Asignada como ciudad levítica (Jos 21:21), Gezer fue testigo tanto de las victorias de David sobre los filisteos (2 S 5:25; 1 Cr 14:16) como de las ambiciosas campañas constructivas de Salomón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1508', 'spa', 'Área separada o recinto junto al templo; también forma pulida o figura que describe belleza corporal', 'Sustantivo derivado de la raíz g-z-r (''cortar, separar''), con dos aplicaciones distintas. En la visión del templo de Ezequiel (capítulos 41-42), designa el ''área separada'': un patio amurallado o espacio abierto en tres lados del edificio del templo, término arquitectónico que aparece siete veces con medidas precisas. En Lamentaciones 4:7, el significado cambia para describir la belleza corporal: la גִּזְרָה de los príncipes era ''como el zafiro,'' apuntando a una forma pulida y esculpida. El sentido raíz de cortar o tallar conecta ambos usos: un espacio cortado de su entorno, y un cuerpo tallado o pulido hasta alcanzar proporciones hermosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1513', 'spa', 'Brasa, ascua ardiente: carbón encendido o brasa viva, usado en contextos de fuego sacrificial, visiones teofánicas y juicio divino. גַּחֶלֶת designa u', 'Brasa, ascua ardiente: carbón encendido o brasa viva, usado en contextos de fuego sacrificial, visiones teofánicas y juicio divino. גַּחֶלֶת designa una brasa viva o ascua incandescente que irradia calor y luz. Sus 18 apariciones en la Biblia hebrea evocan consistentemente una energía ardiente e intensa, ya sea fuego literal sobre el altar o fuego figurativo en la mano de Dios. El plural גֶּחָלִים aparece con mayor frecuencia, típicamente en la frase constructa גַּחֲלֵי־אֵשׁ (''brasas de fuego''). En Levítico 16:12, el sumo sacerdote toma un incensario lleno de brasas de fuego del altar para el incienso del Día de la Expiación. Los grandes salmos teofánicos describen la aparición de Dios con lenguaje de tormenta: brasas de fuego ardían delante de él (2 Sam 22:9, 13 = Sal 18:8, 12-13). La visión inaugural de Ezequiel compara a las criaturas vivientes con brasas ardientes (Ez 1:13; 10:2). Proverbios emplea la imagen de manera práctica y proverbial (Prov 6:28; 26:21), e Isaías la usa para fuego doméstico (Isa 44:19; 47:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1516', 'spa', 'gay — valle, barranco; una depresión geográfica entre colinas, frecuentemente en nombres de lugar.', 'gay — valle, barranco; una depresión geográfica entre colinas, frecuentemente en nombres de lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1517', 'spa', 'Tendón, nervio; tejido fibroso que conecta músculo con hueso, usado literal y figuradamente para la obstinación', 'Designa un tendón o nervio, el tejido conectivo resistente del cuerpo. En su uso más memorable, nombra el ''tendón de la cadera'' (גִּיד הַנָּשֶׁה) que fue tocado durante la lucha de Jacob en Peniel (Gn 32:32), dando origen a una ley dietética perdurable. La palabra también aparece en un vigoroso lenguaje figurado: Isaías 48:4 describe la obstinación de Israel como un ''tendón de hierro'' en el cuello. Cognado del arameo גִּידָא y relacionado con el árabe jīd (cuello), el término abarca tanto la descripción anatómica como una poderosa metáfora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1518', 'spa', 'giach -- brotar con fuerza, irrumpir; del agua que brota, de un niño que emerge del vientre', 'El verbo giach (también guach) significa brotar o salir con fuerza. Sus seis apariciones abarcan imágenes vivas: un río que surge en Job 40:23, el mar primordial brotando del vientre en Job 38:8, Dios sacando al niño del cuerpo de la madre en Salmo 22:9, el mandato de Miqueas de «retorcerte y dar a luz» (Miq 4:10), guerreros irrumpiendo desde una emboscada (Jue 20:33), y Egipto agitándose como un cocodrilo (Ez 32:2). La palabra oscila entre la emergencia física literal y la erupción figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1521', 'spa', 'Gihón -- (1) un río del Edén; (2) el manantial cerca de Jerusalén usado para la unción real', 'Gihón (que significa «un brotar», de la raíz g-y-ch «manar») designa dos fuentes de agua distintas en la Escritura. La primera es uno de los cuatro ríos del Edén (Gn 2:13), que se dice rodeaba la tierra de Cus, cuya identificación precisa ha sido largamente debatida. La segunda es el célebre manantial al este de Jerusalén, identificado hoy con la «Fuente de la Virgen» (Ain Umm ed-Daraj), cuyas aguas Ezequías canalizó a través de su famoso túnel (2 Cr 32:30). En este Gihón fue ungido Salomón como rey (1 R 1:33, 38, 45), deliberadamente fuera de las murallas en una ceremonia pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1522', 'spa', 'Giezi -- siervo del profeta Eliseo, conocido por su codicia y la lepra resultante', 'Giezi -- siervo del profeta Eliseo, conocido por su codicia y la lepra resultante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1523', 'spa', 'Regocijarse, exultar, alegrarse; jubilación expresiva frecuentemente emparejada con שִׂמְחָה en contextos de adoración', 'Regocijarse, exultar, alegrarse; jubilación expresiva frecuentemente emparejada con שִׂמְחָה en contextos de adoración');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1524a', 'spa', 'Regocijo, exultación; gozo intenso comunitario o religioso, frecuentemente paralelo a simchah', 'Sustantivo de la raíz g-y-l que significa ''girar de gozo,'' y transmite una alegría exuberante, casi física. En los Salmos aparece como ''el gozo de mi regocijo'' (Sal 43:4) y como un clamor que brota de los propios prados (Sal 65:12). Los textos proféticos lo emparejan con שִׂמְחָה para describir la alegría festiva que Dios retira como juicio: el gozo del lagar cesa en Moab (Is 16:10; Jer 48:33) y la celebración de la cosecha es arrebatada de Israel (Jl 1:16). Oseas advierte a Israel que no se regocije ''hasta la exultación'' como las naciones (Os 9:1), mostrando que el verdadero גִּיל pertenece a la relación de pacto con Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1530', 'spa', 'Montón, ola, oleaje (de agua o grano)', 'Montón, ola, oleaje (de agua o grano)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1531', 'spa', 'cuenco, tazón; recipiente redondeado para lámparas de aceite o capiteles decorativos sobre columnas', 'Este término describe objetos con forma de cuenco que cumplen diversas funciones. En la visión nocturna de Zacarías, un cuenco de oro contiene aceite para el candelabro, alimentado por dos olivos. Eclesiastés lo usa metafóricamente en una imagen de la muerte: el cuenco de oro que se quiebra. El templo de Salomón presentaba cuencos decorativos como capiteles en lo alto de las columnas. Jueces y Josué mencionan manantiales o depósitos de agua con este nombre, posiblemente refiriéndose a formaciones naturales semejantes a estanques. El elemento constante es la forma curva de cuenco, ya sea en recipientes literales, elementos arquitectónicos o formaciones naturales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1533', 'spa', 'Gilboa (cadena montañosa donde murió Saúl)', 'Esta cadena montañosa en el norte de Israel se hizo tristemente célebre como el lugar de la última batalla y muerte de Saúl. Los libros de Samuel y Crónicas mencionan repetidamente a Gilboa en relación con esta derrota catastrófica ante los filisteos. El lamento de David en 2 Samuel 1:21 maldice estas montañas: ''¡Que no haya rocío ni lluvia sobre vosotros, montes de Gilboa!'' El nombre podría significar ''manantial burbujeante'' o relacionarse con aridez, algo irónicamente apropiado dada la maldición de David. El sitio geográfico sigue siendo identificable en el Israel moderno, dando testimonio de aquella antigua tragedia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1534', 'spa', 'Rueda o mecanismo de ruedas (de carros o de la visión del trono de Ezequiel); también torbellino o polvo arremolinado impulsado por el viento', 'Rueda o mecanismo de ruedas (de carros o de la visión del trono de Ezequiel); también torbellino o polvo arremolinado impulsado por el viento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1537', 'spa', 'Gilgal (múltiples sitios: ''círculo de piedras'') — nombre propio de varias localidades bíblicas, la más célebre cerca de Jericó, donde Israel acampó tr', 'Gilgal (múltiples sitios: ''círculo de piedras'') — nombre propio de varias localidades bíblicas, la más célebre cerca de Jericó, donde Israel acampó tras cruzar el Jordán y erigió piedras conmemorativas. El nombre significa ''círculo'' o ''rueda'', aludiendo a círculos de piedras en estos santuarios. Josué 4-5 establece a Gilgal como el primer centro de culto israelita en Canaán, donde se renovó la circuncisión y se celebró la Pascua. Otros textos mencionan un Gilgal en Benjamín y posiblemente otro en el norte de Israel. Los profetas a veces criticaron el culto corrupto de Gilgal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1538', 'spa', 'Cráneo, cabeza (estructura ósea)', 'Cráneo, cabeza (estructura ósea)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1540', 'spa', 'Descubrir, revelar, ir al exilio -- verbo de exposición y desplazamiento: literal (desnudez, cobertura) o abstracto (secretos, verdad divina); causativos = deportar.', 'Este verbo (186x) opera a lo largo de un espectro que va desde el descubrimiento físico hasta la revelación divina y el desplazamiento forzoso. En Qal significa ''ir al exilio'' o ''revelar''; en Piel, ''descubrir'' (especialmente la desnudez) o ''dar a conocer'' (secretos); en Hifil, ''deportar, desterrar''; en Nifal, ''ser revelado, manifestarse''. El puente semántico entre ''descubrir'' y ''exiliar'' refleja probablemente la idea de ser arrancado de la patria. El árabe جَلَا (emigrar, descubrir), el español descubrir/revelar y desterrar/deportar reflejan esta misma polisemia. La evidencia multilingüe muestra que exposición y desplazamiento se agrupan en zonas semánticas distintas pero emparentadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1541', 'spa', 'exilio, cautiverio (estado de ser descubierto o removido de la propia tierra)', 'Forma sustantiva de la raíz ''descubrir'', este término designa específicamente el exilio o cautiverio: el estado de ser arrancado de la propia tierra. Aparece con frecuencia en la literatura profética anunciando o describiendo la deportación babilónica. Ezequiel lo emplea extensamente; Amós habla de Israel yendo ''al destierro más allá de Damasco''. La palabra capta la esencia del exilio: Israel ''descubierto'' o ''expuesto'', despojado de la tierra que revestía su identidad pactual. El uso judío posterior lo convirtió en término técnico para la existencia en la diáspora, conservando la imagen de desplazamiento y exposición incluso siglos después del retorno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1543', 'spa', 'Tazón, cuenco (vasija redondeada); fuente, manantial — un receptáculo cóncavo, ya sea artesanal o natural.', 'El sustantivo גֻּלָּה designa una vasija o receptáculo redondeado y cóncavo, ramificándose en dos ámbitos: tazones elaborados y fuentes naturales. En el templo de Salomón, las גֻּלֹּת son los capiteles en forma de cuenco que coronan las columnas de bronce Jaquín y Boaz (1 R 7:41-42), y en la visión del candelabro de Zacarías, la גֻּלָּה es el depósito de aceite que alimenta las siete lámparas (Zac 4:2-3). El tazón de oro de Eclesiastés 12:6 forma parte de una sobrecogedora alegoría de la muerte. La otra rama denota fuentes naturales: cuando Acsa pide a Caleb una bendición, recibe las ''fuentes de arriba y de abajo'' — las גֻּלֹּת de Jos 15:19 y Jue 1:15.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1544', 'spa', 'Ídolos — término despectivo para dioses falsos, de una raíz que sugiere estiércol o bloques informes.', 'Ídolos — término despectivo para dioses falsos, de una raíz que sugiere estiércol o bloques informes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1546', 'spa', 'Exilio, cautividad; colectivamente, la comunidad de deportados llevados lejos de su patria.', 'Sustantivo femenino que captura tanto la amarga condición del desplazamiento forzado como el pueblo que la padece. En su sentido abstracto marca el inicio de la cautividad — Ezequiel fecha sus visiones por ''el año de nuestro exilio'' (Ez 1:2; 33:21; 40:1), y la liberación de Jeconías se cuenta desde el año de su destierro (2 R 25:27). En su sentido colectivo nombra a la comunidad exiliada misma: ''los cautivos de Judá'' a quienes Dios promete restaurar (Jer 24:5; 28:4; 29:22), o ''mis cautivos'' a quienes el SEÑOR declara libres por medio de Ciro (Is 45:13). Amós condena a Filistea y Tiro por traficar con comunidades enteras de deportados (Am 1:6, 9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1547', 'spa', 'Exilio, cautiverio (arameo); el estado de deportación o la comunidad de desterrados', 'Sustantivo arameo que aparece exclusivamente en los libros bíblicos tardíos, referido a la condición de exilio o a la comunidad exiliada en sí. En Esdras 6:16 los «hijos del cautiverio» (בְּנֵי גָלוּתָא) celebran la dedicación del templo, marcando su identidad como comunidad restaurada de deportados. Daniel emplea el término para identificar a Daniel mismo como uno traído del exilio de Judá (Dn 2:25; 5:13; 6:13). Es el cognado arameo del hebreo גּוֹלָה, y abarca tanto el estado abstracto de destierro como el grupo concreto de exiliados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1548', 'spa', 'Rasurar, afeitar (cabello, barba, cabeza); ser rasurado (pasivo); rasurarse a sí mismo (reflexivo)', 'Rasurar, afeitar (cabello, barba, cabeza); ser rasurado (pasivo); rasurarse a sí mismo (reflexivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1551', 'spa', 'Galilea; el distrito septentrional de Israel, región asociada con las naciones y las tribus de Naftalí y Zabulón', 'Término geográfico derivado de la raíz hebrea que significa «circuito» o «distrito», usado exclusivamente como nombre propio para la región septentrional de Israel conocida como Galilea. La zona albergaba una población mixta, lo que le valió el epíteto «Galilea de las naciones» (Is 9:1). Las seis apariciones se refieren al mismo territorio, con fórmulas preposicionales como «Cedes en Galilea» (Jos 20:7; 1 Cr 6:76) y «la tierra de Galilea» (1 R 9:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1552', 'spa', 'Región, distrito, circuito; territorio delimitado, usado especialmente para las regiones filisteas o las del Jordán.', 'Sustantivo femenino que significa ''región'', ''distrito'' o ''circuito'', derivado de la raíz גָּלַל (''rodar, girar''). Designa un territorio delimitado o distrito administrativo. En Jos 13:2 y Jl 3:4 (hebreo 4:4), ''todas las regiones de los filisteos'' marca territorio aún por conquistar. Jos 22:10-11 lo emplea para la región junto al Jordán donde las tribus orientales erigieron su controvertido altar. Ez 47:8 se refiere a ''la región oriental'' en la geografía visionaria. Cabe destacar que la forma relacionada גָּלִיל dio origen al nombre ''Galilea'' —el ''circuito'' de las naciones— mostrando cómo un sustantivo común se convirtió en célebre topónimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1555', 'spa', 'Goliat; el gigante filisteo de Gat, campeón derrotado por David', 'Nombre propio del famoso guerrero filisteo de Gat que se presentó como campeón contra el ejército de Israel. Goliat es descrito como un gigante cuya estatura y armadura lo convertían en un adversario temible. La victoria de David sobre Goliat con una honda y una piedra (1 S 17) se convirtió en uno de los relatos más emblemáticos de la Escritura. Una nota textual interesante surge de 2 Samuel 21:19, que atribuye la muerte de Goliat a Elhanán, mientras que 1 Crónicas 20:5 armoniza indicando que Elhanán mató al hermano de Goliat, Lahmi.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1556', 'spa', 'Rodar, quitar rodando; reflexivamente, revolcarse; idiomáticamente, encomendar o confiar el camino a Dios; enrollar o plegar. גָּלַל es un verbo marav', 'Rodar, quitar rodando; reflexivamente, revolcarse; idiomáticamente, encomendar o confiar el camino a Dios; enrollar o plegar. גָּלַל es un verbo maravillosamente físico: el golpe pesado de una piedra al ser rodada de la boca de un pozo o a través de la entrada de una cueva es su territorio natural (Gén 29:3, 8, 10; Jos 10:18). Pero el hebreo lleva esta imagen concreta a usos sorprendentes. El salmista ''rueda'' su camino sobre el SEÑOR (Sal 37:5; Prov 16:3), usando la transferencia de peso del rodar piedras como metáfora para encomendar las cargas a Dios. Guerreros se revuelcan en sangre (2 Sam 20:12), los cielos se ''enrollan'' como un pergamino (Isa 34:4), y la justicia ''rueda'' como las aguas (Amós 5:24). Las variaciones de conjugación hebrea reflejan estas extensiones semánticas de manera natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1558', 'spa', 'Por causa de, a causa de, por motivo de -- preposición causal que expresa razón o causa', 'Por causa de, a causa de, por motivo de -- preposición causal que expresa razón o causa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1559', 'spa', 'Galal — nombre de levita que significa «estiércol» o «rodar», presente en listas postexílicas', 'Galal es el nombre de dos levitas en genealogías postexílicas (1 Cr 9:15-16, Neh 11:17). Probablemente deriva de una raíz que significa «rodar» (quizá «estiércol» en sentido despectivo, o simplemente «rodador»). Pese a su significado potencialmente humilde, estos levitas sirvieron en la comunidad restaurada del templo. La repetición del nombre sugiere que no era infrecuente entre familias levíticas. Como muchos nombres bíblicos, pudo haber conmemorado circunstancias del nacimiento o expresado la teología de los padres, aunque su significado exacto se nos escapa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1561', 'spa', 'Estiércol, excremento; desecho animal o humano, especialmente seco y usado como combustible', 'Se refiere al estiércol o excremento, con el matiz distintivo de desecho moldeado en tortas redondeadas — el cognado árabe jilla designa específicamente boñigas de camello formadas en bolas. Ezequiel 4:12 y 4:15 ofrecen el uso más vívido: Dios ordena al profeta cocer pan sobre excremento humano como señal de la contaminación de Israel, y luego permite sustituirlo por estiércol de vaca. En Job 20:7 el impío perece «como su propio estiércol», imagen gráfica de total insignificancia. Sofonías 1:17 extiende esta figura a la sangre derramada como polvo y la carne como estiércol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1565', 'spa', 'Estéril, desolado/a, duro/a; lo que es improductivo, solitario o demacrado.', 'Adjetivo que evoca una esterilidad cruda e implacable, ya sea de una noche que se desea sin gozo (Job 3:7), de la congregación de los impíos descrita como infructuosa (Job 15:34), o de figuras demacradas por el hambre (Job 30:3). En Isaías 49:21 se aplica a Sion personificada como mujer enlutada y sin hijos que se asombra al descubrir nueva descendencia. El cognado árabe jalmad (''roca, terreno pedregoso'') ancla la imagen en un suelo duro e infecundo, mientras que el arameo galmuda refuerza el sentido de aislamiento desolado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1566', 'spa', 'estallar en contienda, provocar riña — iniciar un conflicto o exponerse en disputa', 'Este verbo en forma hitpael aparece tres veces en Proverbios y describe el estallido o la provocación de una contienda. Proverbios 17:14 advierte que iniciar una riña es como soltar aguas: antes de que estalle la disputa, hay que abandonarla. Proverbios 18:1 describe al necio que se enfrenta contra todo buen juicio. Proverbios 20:3 enseña que evitar la contienda es honroso, mientras que todo necio se enreda en pleitos. El verbo puede derivar de raíces que significan «exponer» o «descubrir», sugiriendo la idea de un conflicto que irrumpe a la vista de todos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1568', 'spa', 'Galaad -- nombre propio de una región montañosa transjordana y del antepasado (nieto de Manasés) que le da nombre.', 'גִּלְעָד designa tanto a una persona como a un territorio al este del Jordán, apareciendo 134 veces a lo largo del Pentateuco, los Profetas Anteriores y la literatura poética. Como nombre personal se refiere al hijo de Maquir y nieto de Manasés (Nm 26:29-30; 27:1). Como término geográfico denota la región montañosa entre el Arnón y el Yarmuk: tierra de pastos fértiles célebre por su bálsamo (Jer 8:22; 46:11) y sus rebaños (Nm 32:1; Cnt 4:1). Jacob y Labán sellaron su pacto en Galaad (Gn 31:21-25), y la región fue escenario destacado de conflictos intertribales (Jue 10-12). La Septuaginta lo transcribe Galaad, forma que el español y el francés mantienen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1569', 'spa', 'Galaadita -- persona oriunda de Galaad, la región montañosa al este del río Jordán', 'Galaadita -- persona oriunda de Galaad, la región montañosa al este del río Jordán');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1571', 'spa', 'También, además; aun, hasta; tanto...como; ciertamente; ni, tampoco; porque también — partícula aditiva-escalar versátil', 'Esta pequeña pero potente partícula hebrea (גַּם) es la herramienta principal del idioma para la adición, el énfasis y la aserción escalar. En su uso más simple significa ''también'' o ''además'', pero según el contexto puede deslizarse hacia el concesivo ''aun'' o ''hasta'', el correlativo ''tanto...como'', el enfático ''ciertamente'' o, en contextos negativos, ''ni'' o ''tampoco''. Sus 769 apariciones abarcan prácticamente todos los géneros y registros de la prosa bíblica. La evidencia multilingüe resulta especialmente reveladora: cuando גַּם significa ''aun'', el suajili cambia de pia a hata, el coreano de 또한 a 심지어 y el árabe de أيضًا a حتّى — distinciones escalares invisibles en algunas lenguas pero nítidas en otras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1573', 'spa', 'Papiro, junco; planta acuática usada para fabricar cestas y embarcaciones.', 'La planta del papiro (Cyperus papyrus), un junco alto y acuático que florecía a lo largo del Nilo y en regiones pantanosas. Su aparición más célebre es en Éxodo 2:3, donde la madre de Moisés fabrica una tevat gome — una cesta de papiro — para poner al niño a flotar sobre el río. Isaías 18:2 menciona ''embarcaciones de papiro'' enviadas sobre las aguas, mientras que Job 8:11 pregunta retóricamente si el papiro puede crecer sin agua. Isaías 35:7 contempla una restauración mesiánica donde el terreno árido se convierte en un pantano de cañas y papiros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1576', 'spa', 'Retribución o recompensa por las obras realizadas; también un beneficio o bondad recibida de Dios. Este sustantivo, derivado de la raíz גָּמַל (tratar', 'Retribución o recompensa por las obras realizadas; también un beneficio o bondad recibida de Dios. Este sustantivo, derivado de la raíz גָּמַל (tratar, madurar), capta el ciclo completo de acción y consecuencia. En la mayoría de sus apariciones denota retribución: ''la recompensa de sus manos le será devuelta'' (Isa 3:11), y el salmista pide a Dios que ''dé a los soberbios su merecido'' (Sal 94:2). Abdías 15 advierte a Edom que sus acciones volverán sobre su propia cabeza. Sin embargo, el Salmo 103:2 transforma completamente la palabra: ''no olvides ninguno de sus beneficios,'' donde גְּמוּל se convierte en la bondad graciosa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1578', 'spa', 'retribución, recompensa — pago justo conforme a las obras, ya sean buenas o malas', 'Este sustantivo femenino designa la retribución o recompensa: el justo pago por los propios actos. En 2 Samuel 19:36, Barzilai declina humildemente la recompensa real preguntando «¿qué galardón merece tu siervo?». Isaías 59:18 advierte que Dios pagará conforme a las obras: retribución a sus adversarios. Jeremías 51:56 llama a Yahvé «Dios de las retribuciones», que ciertamente paga. La palabra deriva de גָּמַל («tratar con, recompensar») y conlleva el sentido de una respuesta medida y apropiada a la conducta, ya sea bendición por fidelidad o juicio por maldad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1580', 'spa', 'Verbo cuyo campo semántico revela una unidad subyacente: llevar algo a su estado pleno y completo. Ya sea retribuir a alguien por lo que hizo (Gn 50:1', 'Verbo cuyo campo semántico revela una unidad subyacente: llevar algo a su estado pleno y completo. Ya sea retribuir a alguien por lo que hizo (Gn 50:15), destetar a un niño del pecho (Gn 21:8), o madurar un fruto en la vid (Nm 17:8), גָּמַל siempre implica un proceso que alcanza su conclusión natural. El clamor del salmista ''Haz bien a tu siervo'' (Sal 119:17) emplea la misma raíz, pidiendo a Dios que lleve su acción generosa a su cumplimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1581', 'spa', 'Camello — la bestia de carga domesticada de una joroba, indicador de riqueza y viaje en el antiguo Cercano Oriente.', 'Camello — la bestia de carga domesticada de una joroba, indicador de riqueza y viaje en el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1583', 'spa', 'Gamaliel (''recompensa de Dios''); príncipe de la tribu de Manasés durante la peregrinación por el desierto.', 'Nombre propio masculino que significa ''recompensa de Dios'' o ''Dios es mi retribución'', llevado por el príncipe de la tribu de Manasés durante el período del desierto. Al igual que Gedeoni (H1441), Gamaliel aparece exclusivamente en las listas tribales formularias de Números: en el censo (1:10), la disposición del campamento (2:20), la dedicación del tabernáculo (7:54, 59) y el orden de marcha (10:23). La transliteración es idéntica en todas las traducciones consultadas (inglés, español, francés, alemán: ''Gamaliel''), un notable consenso. El mismo nombre reaparece siglos después en el famoso rabí Gamaliel de Hechos 5:34, maestro de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1584', 'spa', 'Acabarse, cesar; completar, llevar a cumplimiento.', 'Verbo poético que aparece exclusivamente en los Salmos, empleado tanto intransitivamente para describir cosas que cesan o llegan a su fin, como transitivamente para expresar que Dios completa o cumple propósitos en favor de su pueblo. En el Salmo 12:1 se usa en paralelo con el raro verbo פָּסַס (''desaparecer''), lamentando la extinción de los fieles. En el Salmo 138:8 expresa la confianza firme de que el SEÑOR llevará a término lo que concierne al salmista. El cognado arameo גְּמַר se convirtió en el término estándar para completar el estudio en el uso rabínico posterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1586', 'spa', 'Gomer; (1) hijo de Jafet, ancestro de un pueblo septentrional; (2) esposa del profeta Oseas', 'Nombre propio que corresponde a dos figuras bíblicas distintas. El primero es Gomer hijo de Jafet, incluido en la Tabla de las Naciones (Gn 10:2; 1 Cr 1:5), identificado por fuentes antiguas con los cimerios o los capadocios de Asia Menor, y mencionado en Ezequiel 38:6 entre los aliados de Gog. La segunda es Gomer hija de Diblaim, la esposa de Oseas, a quien Dios ordenó al profeta desposar como parábola viviente de la infidelidad de Israel (Os 1:3). Este doble uso convierte al nombre en una ventana fascinante tanto a la etnografía como al simbolismo profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1587', 'spa', 'Gemarías, ''Yah ha cumplido''; nombre de dos hombres en el libro de Jeremías.', 'Nombre personal teofórico que significa ''el SEÑOR ha cumplido'' o ''Yah ha completado'', formado a partir de la raíz גָּמַר (H1584). Dos hombres distintos llevan este nombre en el libro de Jeremías. El primero, hijo de Safán el escriba, poseía una cámara en el templo donde Baruc leyó en voz alta el rollo de Jeremías (Jer 36:10-12, 25) y fue uno de quienes instaron al rey Joacim a no quemar el rollo. El segundo, hijo de Hilcías, sirvió como enviado que llevó la carta de Jeremías a los exiliados en Babilonia (Jer 29:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1588', 'spa', 'Área cultivada y cercada destinada al cultivo de plantas, hortalizas, hierbas o árboles. La palabra está indisolublemente ligada al jardín del Edén (G', 'Área cultivada y cercada destinada al cultivo de plantas, hortalizas, hierbas o árboles. La palabra está indisolublemente ligada al jardín del Edén (Gn 2:8-16), y reaparece a lo largo de las Escrituras para jardines reales (2 R 21:18; Est 1:5), jardines de recreo (Ec 2:5) y jardines metafóricos que representan a la amada en el Cantar de los Cantares (4:12, 16; 5:1). Una ocurrencia en 2 Reyes 9:27 puede funcionar como topónimo propio (''Beth-haggán'', la casa del jardín).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1589', 'spa', 'El verbo גָּנַב es la palabra principal de la Biblia hebrea para el robo y aparece en el mandamiento ''No robarás'' (Éx 20:15; Dt 5:19). Su campo semánt', 'El verbo גָּנַב es la palabra principal de la Biblia hebrea para el robo y aparece en el mandamiento ''No robarás'' (Éx 20:15; Dt 5:19). Su campo semántico va mucho más allá del hurto de bienes. Cuando Raquel ''robó'' los ídolos de Labán (Gn 31:19), cuando Absalón ''robó los corazones'' del pueblo (2 S 15:6) y cuando Joás fue rescatado en secreto (2 R 11:2), la misma raíz abarca engaño, seducción, secuestro y rescate furtivo. La forma reflexiva hitpael (''escabullirse'') revela soldados que se escurren avergonzados (2 S 19:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1590', 'spa', 'Ladrón: persona que roba, ya sea un asaltante común, secuestrador o figura metafórica de sigilo. Se refiere a quien roba, abarcando desde el ladrón qu', 'Ladrón: persona que roba, ya sea un asaltante común, secuestrador o figura metafórica de sigilo. Se refiere a quien roba, abarcando desde el ladrón que irrumpe en una casa hasta el secuestrador. El Código de la Alianza distingue al ladrón sorprendido entrando de noche del sorprendido de día (Éx 22:1-7). Los profetas usan la figura con fuerza: Isaías acusa a los líderes de Israel de ser compañeros de ladrones (Isa 1:23), Joel compara un ejército invasor con ladrones que entran por las ventanas (Joel 2:9), y Zacarías imagina un rollo volador que maldice a todo ladrón (Zac 5:4). Deuteronomio 24:7 extiende el término a quien secuestra y esclaviza a un hermano israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1593', 'spa', 'gannah -- jardín, huerto; parcela de tierra cultivada y cercada, frecuentemente irrigada, para árboles o plantas', 'gannah -- jardín, huerto; parcela de tierra cultivada y cercada, frecuentemente irrigada, para árboles o plantas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1594', 'spa', 'Jardín, huerto; recinto cultivado para plantas, frutas o flores.', 'Sustantivo femenino que designa un jardín o huerto cultivado, estrechamente emparentado con el más frecuente גַּן. Sus cuatro apariciones se agrupan en dos contextos: el jardín del pabellón real en Ester (ginnat bitan, Est 1:5; 7:7–8) y el huerto de nogales del Cantar de los Cantares 6:11 (ginnat egoz). Los pasajes de Ester pintan una escena vívida: el banquete del rey se extiende al jardín del palacio, y la suerte de Amán se sella cuando el rey regresa de ese mismo jardín. El uso en Cantares evoca intimidad y deleite.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1595', 'spa', 'cofres, tesoros — arcas de almacenamiento o casas del tesoro real', 'Este sustantivo plural tiene dos posibles acepciones: (1) cofres o arcas, especialmente para telas valiosas (Ez 27:24), y (2) tesoros o depósitos de riqueza real (Est 3:9; 4:7). La palabra puede ser un préstamo del persa, y aparece en contextos de comercio internacional y administración imperial. En Ezequiel se refiere a mercancías en el mercado de Tiro. En Ester designa las arcas del rey en las que Amán promete depositar dinero a cambio del derecho a destruir a los judíos. El rango semántico, desde cofres portátiles hasta tesoros fijos, refleja los ámbitos del comercio y las finanzas estatales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1596', 'spa', 'tesoros, tesorerías (arameo) — casas de tesoros reales o del templo en Esdras', 'Este sustantivo arameo aparece únicamente en Esdras, refiriéndose a las tesorerías reales persas donde se guardaban documentos oficiales y recursos. Esdras 5:17 y 6:1 mencionan «la casa de los tesoros del rey» en Babilonia, donde se buscó el decreto de Ciro. Esdras 7:20 autoriza fondos «de la casa de los tesoros del rey». La palabra es el equivalente arameo del hebreo גְּנָזִים, ambos posiblemente derivados del persa. Refleja el aparato administrativo del Imperio persa, con su meticuloso registro de archivos y control financiero centralizado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1598', 'spa', 'Defender, proteger, amparar; usado exclusivamente de Dios defendiendo Jerusalén y a su pueblo de los enemigos.', 'Este verbo significa cubrir protectoramente, rodear y defender. Cada aparición bíblica tiene a Dios como sujeto: protegiendo Jerusalén del asedio asirio (2 Re 19:34; 20:6; Is 37:35; 38:6) o cernido sobre la ciudad como aves que protegen su nido (Is 31:5). Zacarías extiende la imagen a Dios defendiendo a su pueblo en la batalla escatológica (Zac 9:15; 12:8). El cognado árabe janna (''cubrir, ocultar'') y el arameo agen confirman el significado raíz de protección envolvente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1599', 'spa', 'Ginetón — nombre sacerdotal entre los exiliados que regresaron en Nehemías', 'Ginetón (o Ginetoi, variante ortográfica) fue un sacerdote que regresó del exilio babilónico y sirvió en la comunidad restaurada de Jerusalén. Aparece en las listas de Nehemías entre los sacerdotes que sellaron el pacto (Neh 10:6) y en los registros genealógicos (Neh 12:4, 16). El nombre posiblemente deriva de una raíz que significa «jardinero» o «protector». BDB señala su parentesco con la forma «Gineto», lo que sugiere que variantes del mismo nombre circulaban entre las familias sacerdotales postexílicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1602', 'spa', 'Aborrecer, detestar con repugnancia visceral; (Nifal) ser contaminado o rechazado; (Hifil) fallar, malograrse', 'Aborrecer, detestar con repugnancia visceral; (Nifal) ser contaminado o rechazado; (Hifil) fallar, malograrse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1603', 'spa', 'Gaal hijo de Ebed, agitador cananeo que lideró una revuelta efímera contra Abimelec en Siquem.', 'Nombre propio de una figura aparentemente cananea que aparece exclusivamente en Jueces 9. Gaal hijo de Ebed llegó a Siquem e incitó a los terratenientes locales contra el gobierno de Abimelec, jactándose durante una fiesta de vendimia de que lo derrocaría (Jue 9:26-29). Cuando Zebul, prefecto de Abimelec, lo desafió, Gaal condujo a sus seguidores a la batalla pero fue derrotado rotundamente y expulsado de la ciudad (Jue 9:35-41). Todas las traducciones principales conservan el nombre uniformemente como ''Gaal'' en inglés, español, francés y alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1605', 'spa', 'Reprender severamente, censurar con autoridad; usado para la corrección humana y la reprensión divina de naciones, el mar y el mal.', 'Verbo que expresa una reprensión verbal enérgica, que va desde un padre que regaña a su hijo (Gn 37:10) hasta Dios reprendiendo a las naciones y a las aguas cósmicas. Cuando Jacob reprende a José, la palabra transmite autoridad paterna; cuando Dios reprende al mar Rojo (Sal 106:9) o a Satanás (Zac 3:2), comunica un mandato soberano que transforma la realidad. Notablemente, los seis idiomas de traducción emplean un único equivalente para cada aparición — en español ''reprender'' — lo que confirma su estrecha unidad semántica en los 14 usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1606', 'spa', 'Reprensión, censura, amenaza — especialmente la reprensión sobrecogedora de Dios.', 'Designa una censura verbal enérgica que abarca desde la reprensión correctiva de un sabio hasta el estallido aterrador de la ira divina. En la literatura sapiencial, una reprensión al hombre sensato vale más que cien azotes al necio (Pr 17:10), y la reprensión del sabio es mejor que el canto de los necios (Ec 7:5). Mucho más dramática es la reprensión de Dios: el mar huye ante ella (Sal 104:7), los cimientos del mundo quedan al descubierto (Sal 18:15) y los guerreros caen aturdidos (Sal 76:6). Isaías vislumbra un día en que mil huirán ante la reprensión de uno solo (Is 30:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1607', 'spa', 'Sacudir, temblar, agitar violentamente; de la tierra y los montes en teofanía, de aguas encrespadas, y figuradamente de naciones que se tambalean bajo', 'Sacudir, temblar, agitar violentamente; de la tierra y los montes en teofanía, de aguas encrespadas, y figuradamente de naciones que se tambalean bajo el juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1608', 'spa', 'Gaas; montaña en Efraín cerca de la sepultura de Josué, con barrancos asociados.', 'Topónimo que identifica una montaña (har Gaas) en la región montañosa de Efraín, al sur de Timnat-sera, donde fue sepultado Josué (Jos 24:30; Jue 2:9). El nombre posiblemente deriva de una raíz que significa ''temblar'' o ''sacudir'', lo cual encaja con un terreno escarpado. En 2 Samuel 23:30 y 1 Crónicas 11:32 se mencionan los ''torrentes de Gaas'' (nahale Gaas), barrancos cercanos a la montaña asociados con Hidai/Hurai, uno de los valientes de David. Las traducciones principales conservan el nombre como ''Gaas'' con variaciones mínimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1609', 'spa', 'Gatam — jefe edomita, hijo de Elifaz y nieto de Esaú', 'Gatam fue uno de los jefes tribales (allufim) descendientes de Esaú a través de su hijo Elifaz (Gn 36:11, 16). También aparece en la genealogía paralela de 1 Crónicas 1:36. Como jefe edomita, habría liderado un clan o región en Edom. La etimología de su nombre es incierta. Representa a uno de los muchos líderes edomitas enumerados en Génesis 36, mostrando el cumplimiento de la promesa de Dios de que Esaú sería padre de naciones, aun cuando la narrativa bíblica se centra principalmente en la línea de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1610', 'spa', 'Cuerpo, persona; también altura o elevación. Se usa para el propio cuerpo o el punto más alto de un lugar.', 'Sustantivo con dos polos semánticos bien diferenciados. En las leyes sobre esclavos de Éxodo (21:3–4) aparece en la expresión begappo (''con su cuerpo / por sí solo''), indicando que un hombre entra o sale de la servidumbre solo, sin esposa ni hijos — el español ''en su soltería'' capta bien este sentido de persona en sí misma. En Proverbios 9:3, sin embargo, pasa a significar ''alturas'' o ''puntos elevados'' (gappe merome qaret, ''las cumbres de la ciudad''), desde donde la Sabiduría personificada llama. El vocablo es cognado del hebreo tardío y arameo guf (''cuerpo''), y el salto semántico de ''cuerpo'' a ''altura'' puede reflejar la idea de la estatura erguida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1611', 'spa', 'ala, alas (arameo) — las alas de las bestias en las visiones de Daniel', 'Este sustantivo arameo para ala(s) aparece únicamente en las visiones apocalípticas de bestias simbólicas de Daniel. La primera bestia (que representa a Babilonia) tenía alas de águila que le fueron arrancadas (Dn 7:4, dos veces). La tercera bestia (que representa a Grecia) tenía cuatro alas de ave en su espalda (Dn 7:6). La palabra es el cognado arameo del hebreo כָּנָף y del siríaco gepa. Las alas en estas visiones simbolizan conquista veloz y poder imperial. La variedad de configuraciones aladas en las distintas bestias comunica sus características particulares y la naturaleza de su dominio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1612', 'spa', 'gephen — vid, parra; la planta cultivada de uva, tanto en sentido literal como figurado para Israel y la bendición.', 'gephen — vid, parra; la planta cultivada de uva, tanto en sentido literal como figurado para Israel y la bendición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1614', 'spa', 'Azufre; mineral combustible asociado con el juicio divino y la destrucción catastrófica', 'Se refiere al azufre, el mineral amarillo combustible que arde con un humo asfixiante. En las Escrituras aparece casi siempre emparejado con fuego como instrumento del juicio devastador de Dios. El caso paradigmático es Génesis 19:24, donde el SEÑOR hace llover azufre y fuego sobre Sodoma y Gomorra. A partir de ahí se convierte en imagen recurrente de la ira divina: el Salmo 11:6 advierte a los impíos de una lluvia de fuego y azufre, e Isaías 30:33 compara el aliento de Dios con un torrente de azufre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1616', 'spa', 'Forastero o extranjero residente que habita en una tierra sin derechos hereditarios, frecuentemente bajo protección legal divina. El גֵּר designa a un', 'Forastero o extranjero residente que habita en una tierra sin derechos hereditarios, frecuentemente bajo protección legal divina. El גֵּר designa a una persona que vive fuera de su patria, residiendo entre un pueblo que no es el suyo y careciendo de los derechos hereditarios sobre la tierra propios de los ciudadanos nativos. Abraham se llama a sí mismo גֵּר en Hebrón (Gn 23:4), y Moisés nombra a su hijo Gersón como un juego de palabras con esta condición (Éx 2:22). La Torá empareja repetidamente al forastero con el huérfano y la viuda como miembros vulnerables de la sociedad a quienes Dios ordena a Israel proteger, amar e incluir en las festividades y el reposo sabático. A través de las traducciones, el término se corresponde uniformemente con ''sojourner'' en inglés, ''extranjero'' en español, ''étranger-résident'' en francés y ''Fremdling'' en alemán, subrayando el reconocimiento universal de esta categoría social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1617', 'spa', 'Gera, nombre de clan o nombre personal benjaminita asociado con Aod y Simei.', 'Nombre propio benjaminita que parece funcionar tanto como nombre personal como designación de clan. Gera aparece listado como hijo de Benjamín (Gn 46:21) y como hijo de Bela y nieto de Benjamín (1 Cr 8:3, 5, 7), lo que sugiere que se convirtió en identificador de familia o clan dentro de la tribu. Las conexiones más significativas son genealógicas: el juez Aod es llamado ''hijo de Gera'' (Jue 3:15), y Simei, quien maldijo a David, es igualmente identificado como ''hijo de Gera'' (2 S 16:5; 19:16, 18; 1 R 2:8). En español varía curiosamente entre ''Gera'', ''Guera'' y ''Guerá'', reflejando incertidumbre sobre la calidad vocálica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1618', 'spa', 'sarna, comezón — enfermedad cutánea que descalifica a sacerdotes y animales del servicio', 'Este sustantivo designa una afección cutánea costrosa, probablemente una forma de dermatitis crónica o eccema. Levítico 21:20 la incluye entre los defectos que descalifican a un sacerdote para ofrecer sacrificios. Levítico 22:22 prohíbe ofrecer a Dios animales con sarna. Deuteronomio 28:27 amenaza a los transgresores del pacto con «la sarna de Egipto» entre otras enfermedades incurables. La afección se consideraba ritualmente contaminante y médicamente problemática. Existen cognados en árabe, arameo, siríaco y acadio, lo que sugiere un término ampliamente difundido para las afecciones cutáneas escamosas y pruriginosas en las culturas del antiguo Oriente Próximo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1619', 'spa', 'Gareb: un guerrero de David y una colina cercana a Jerusalén', 'El nombre Gareb se refiere a dos entidades distintas. Como persona, Gareb fue uno de los valientes de David, miembro del grupo de los Treinta (2 Sam 23:38; 1 Cr 11:40), probablemente originario de una tribu del norte. Como lugar, el collado de Gareb aparece en la profecía de restauración de Jerusalén en Jeremías 31:39, donde marca el límite occidental de la ciudad reconstruida. El nombre podría derivar de una raíz que significa «sarnoso» o «escamoso», aunque esta conexión es incierta. Tanto la persona como el lugar conservan el nombre en la tradición bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1621', 'spa', 'Cuello, garganta; la parte frontal del cuello, usada figuradamente como lugar para adornar con sabiduría.', 'Sustantivo femenino plural que aparece exclusivamente en Proverbios, siempre en expresiones figuradas sobre adornar el cuello con sabiduría, instrucción o virtud. La enseñanza de los padres es «collar para tu cuello» (Prov 1:9), la misericordia y la verdad deben atarse «a tu cuello» (3:3), y el mandamiento se convierte en «gracia para tu cuello» (3:22; 6:21). La forma reduplicada (de la raíz g-r-r) puede aludir a la garganta, y la constante asociación con imágenes ornamentales —collares, cadenas, ataduras— hace de este término una poderosa metáfora de la sabiduría internalizada que se vuelve adorno visible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1622', 'spa', 'Gergeseo; uno de los siete pueblos cananeos desplazados por Israel, territorio desconocido', 'Nombre gentilicio de los gergeseos, una de las siete naciones tradicionales de Canaán que Israel debía desposeer al entrar en la Tierra Prometida. A pesar de aparecer en las principales listas de pactos y conquistas (Gn 15:21, Dt 7:1, Jos 3:10, Jos 24:11, Neh 9:8), su territorio específico permanece sin identificar. Figuran como descendientes de Canaán en la Tabla de las Naciones (Gn 10:16 = 1 Cr 1:14). El nombre aparece con artículo (הַגִּרְגָּשִׁי) como sustantivo colectivo, y en español se traduce como ''gergeseo'' o ''guirgaseo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1624', 'spa', 'Suscitar contienda, provocar, contender; en Hitpael, entablar conflicto o hacer guerra contra alguien.', 'Verbo combativo cuyos dos temas verbales pintan facetas complementarias del conflicto. En Piel significa suscitar o incitar contienda, como en Proverbios: «El hombre iracundo suscita contiendas» (Pr 15:18; 29:22). El Hitpael pasa al enfrentamiento recíproco: provocarse contra alguien, contender o hacer guerra. Dios advierte a Israel que no «contienda con» Edom, Moab ni Amón (Dt 2:5, 9, 19), y las visiones de Daniel describen reyes que «hacen guerra» unos contra otros (Dn 11:10, 25). El español distingue bien «suscita» (Piel) de «contender / prepararse para guerra» (Hitpael), reflejando el cambio de la incitación causativa al combate activo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1625', 'spa', 'Rumia — alimento regurgitado que mastican los rumiantes, central en la distinción levítica entre animales puros e impuros', 'Rumia — alimento regurgitado que mastican los rumiantes, central en la distinción levítica entre animales puros e impuros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1626', 'spa', 'Gera, unidad mínima de peso israelita equivalente a una vigésima parte de un siclo', 'Término técnico de medición que designa la unidad de peso más pequeña del sistema israelita, definida de manera constante como una vigésima parte de un siclo. Aparece exclusivamente en pasajes que establecen formalmente el valor del siclo: las instrucciones para el impuesto del santuario (Ex 30:13), las tasaciones de redención (Lv 27:25; Nm 3:47; 18:16) y la norma del templo futuro de Ezequiel (Ez 45:12). El cognado asirio giru confirma su antiguo arraigo en los sistemas monetarios del Cercano Oriente. Las traducciones en diversas lenguas conservan el vocablo como préstamo lingüístico: ''gera'' en español, ''guera'' en francés, ''gerah'' en inglés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1627', 'spa', 'Garganta como órgano de la voz y la deglución; también el cuello exterior como parte visible del cuerpo, adornada o exhibida.', 'Sustantivo que designa la parte frontal del cuello humano, abarcando tanto la garganta interna como el cuello externo. Como garganta, aparece en contextos de esfuerzo vocal: ''mi garganta está reseca'' de tanto clamar (Sal 69:3), y como conducto del habla: ''sepulcro abierto es su garganta'' (Sal 5:9), y ''clama a voz en cuello, no te detengas, alza tu voz como trompeta'' (Is 58:1). Como cuello, se refiere a la parte exterior visible, adornada con joyas (Ez 16:11) o exhibida en postura altiva (Is 3:16). El cognado árabe jiran, que designa la parte frontal del cuello de un camello, confirma el aspecto externo y visible de esta parte del cuerpo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1630', 'spa', 'Gerizim; monte en el centro de Israel al sur de Siquem, asociado con las bendiciones del pacto.', 'Nombre del monte situado al sur de Siquem (la actual Nablus) que sirvió como monte de la bendición en la ceremonia de renovación del pacto de Israel. En Deuteronomio 11:29 y 27:12, Moisés ordena que las bendiciones se proclamen desde el monte Gerizim mientras las maldiciones se pronuncian desde el monte Ebal, al frente. Josué 8:33 registra el cumplimiento de este mandato. Jueces 9:7 sitúa a Jotam en Gerizim cuando pronuncia su célebre fábula contra Abimelec. Este monte se convirtió posteriormente en el lugar sagrado de la comunidad samaritana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1631', 'spa', 'Hacha; herramienta para cortar madera, usada en la tala de árboles y en trabajos de construcción.', 'Término directo para designar un hacha o herramienta de corte, que aparece en contextos de tala de árboles, guerra de asedio y construcción del templo. En Deuteronomio 19:5, la cabeza del hacha se desprende del mango durante la tala, ilustrando un daño accidental. Isaías 10:15 lo emplea en una memorable pregunta retórica: ¿puede el hacha jactarse contra quien la maneja?, desafiando la arrogancia de Asiria ante Dios. Las traducciones multilingües lo traducen uniformemente como «hacha», confirmando un sentido concreto único sin derivación semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1632', 'spa', 'adjetivo de significado incierto; posiblemente «grande» en forma constructa, variante textual', 'Esta palabra aparece una sola vez, en un texto disputado de Proverbios relativo a gran ira o furia. Las versiones antiguas y la mayoría de los eruditos modernos la interpretan como otra palabra que significa «grande», lo que sugiere una variante de escriba. La incertidumbre refleja el desafío de interpretar los hápax legómena, es decir, palabras que aparecen una única vez. El contexto apunta a algo relacionado con la magnitud o intensidad de la cólera, pero la precisión se nos escapa. Estos enigmas textuales nos recuerdan que no todos los detalles del hebreo antiguo permanecen perfectamente claros a pesar de la diligencia de los estudiosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1634', 'spa', 'Hueso; por extensión, fortaleza, complexión ósea; sustancia propia, mismísimo', 'Sustantivo que designa el hueso o la estructura esquelética, con sentidos extendidos que siguen la misma lógica metafórica de su sinónimo עֶצֶם: del hueso físico a la fuerza inherente, y de la sustancia corporal a la idea de ''uno mismo'' o ''mismísimo''. La bendición de Jacob describe a Isacar como un ''asno huesudo'', es decir, robusto y fuerte (Gn 49:14). Proverbios lo emplea figuradamente: un espíritu quebrantado seca los huesos (17:22) y la lengua apacible quiebra el hueso (25:15). Los cognados arameo y árabe preservan el sentido primario de cuerpo o hueso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1637', 'spa', 'La era es uno de los escenarios más evocadores de la Biblia: un terreno plano y expuesto donde el grano cosechado se separa de la paja mediante la tri', 'La era es uno de los escenarios más evocadores de la Biblia: un terreno plano y expuesto donde el grano cosechado se separa de la paja mediante la trilla y el aventamiento. Es donde Rut se encuentra con Booz en una escena cargada de significado pactal (Rt 3:2-14), donde David compra la era de Arauna para edificar un altar que se convertiría en el sitio del Templo (2 S 24:18-24; 2 Cr 3:1), y donde Oseas advierte que la prosperidad infiel de Israel se desvanecerá como paja arrastrada de la era (Os 9:1-2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1639', 'spa', 'Disminuir, sustraer o reducir; en raíces pasivas, ser retirado o descontado; también trasquilar el cabello; raramente, retener o extraer hacia arriba', 'Disminuir, sustraer o reducir; en raíces pasivas, ser retirado o descontado; también trasquilar el cabello; raramente, retener o extraer hacia arriba');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1641', 'spa', 'Arrastrar, llevarse por la fuerza; rumiar; aserrar; barrer, arremolinar (tormenta)', 'Verbo cuyo sentido central es arrastrar o tirar, del cual se derivan varios usos especializados según sus formas verbales. En Qal describe el arrastre violento, como cuando los caldeos barren naciones con su red (Hab 1:15) o la violencia arrastra a los malvados (Pr 21:7). El Nifal designa la acción de rumiar, literalmente un movimiento repetitivo de tracción en la mandíbula (Lv 11:7). El Poel describe piedras cortadas con sierra (1 R 7:9) y el Hitpoel una tormenta que se arremolina y ruge (Jer 30:23). Los cognados árabe jarra y asirio gararu conservan la semántica básica de ''arrastrar/tirar''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1642', 'spa', 'Gerar — antigua ciudad en el Néguev al sur de Gaza, prominente en los relatos de Abraham e Isaac', 'Gerar — antigua ciudad en el Néguev al sur de Gaza, prominente en los relatos de Abraham e Isaac');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1644', 'spa', 'Verbo de remoción forzosa que abarca desde la expulsión de Adán del Edén (Gn 3:24) hasta el destierro de naciones ante Israel y la separación legal de', 'Verbo de remoción forzosa que abarca desde la expulsión de Adán del Edén (Gn 3:24) hasta el destierro de naciones ante Israel y la separación legal de una esposa en el divorcio. El Piel intensifica la acción de expulsar, mientras que el participio pasivo גְּרוּשָׁה se convierte en un término casi técnico para la mujer divorciada en la ley sacerdotal. En su imagen más vívida, Isaías 57:20 compara a los impíos con un mar tempestuoso que no puede descansar y que arroja lodo sin cesar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1647', 'spa', 'Gershom — nombre propio que significa ''forastero allí'', llevado por el primogénito de Moisés y varios levitas.', 'Nombre propio masculino explicado por etimología popular como «un extranjero allí» (de גֵּר שָׁם), dado inicialmente por Moisés a su hijo primogénito en Madián porque «fui forastero en tierra extranjera» (Éx 2:22). El nombre reaparece para un ancestro levítico (1 Cr 6:16-17, a menudo intercambiable con Gershón) y un descendiente de Fineas que regresó con Esdras (Esd 8:2). En español se traduce como «Guersom/Gershom», mientras que en francés varía entre «Guerschom» y «Gershom», reflejando los desafíos que las guturales y sibilantes de este nombre plantean en distintas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1648', 'spa', 'Gersón: hijo primogénito de Leví y antepasado del clan levítico gersonita. Nombre propio del primogénito de Leví, progenitor de uno de los tres grande', 'Gersón: hijo primogénito de Leví y antepasado del clan levítico gersonita. Nombre propio del primogénito de Leví, progenitor de uno de los tres grandes clanes levíticos responsables de transportar las cubiertas, cortinas y colgaduras del tabernáculo durante las peregrinaciones por el desierto (Núm 3:25; 4:22-28). La variante ortográfica Gersón (גֵּרְשֹׁם) aparece en varios pasajes de Crónicas (1 Cr 6:1, 28; 15:7), y ambas formas se tratan como intercambiables. El nombre podría derivar de גָּרַשׁ (''expulsar''), evocando el motivo del exilio, aunque esta etimología es debatida. La fórmula ''hijos de Gersón'' domina las apariciones del nombre en Números, Josué y Crónicas en relación con deberes, asignaciones y genealogías levíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1649', 'spa', 'Gersonita — adjetivo gentilicio para los descendientes de Gershón hijo de Leví, usado colectiva o individualmente.', 'Adjetivo gentilicio que identifica a los miembros del clan levítico descendiente de Gershón (también Gershom), el hijo mayor de Leví. En Números 3-4 y 26, los gersonitas reciben deberes específicos del tabernáculo —transportar las cortinas, cubiertas y colgaduras de la tienda— y se les asigna acampar al oeste del tabernáculo. Josué 21:33 registra las ciudades que les fueron asignadas. En Crónicas, gersonitas individuales aparecen en funciones de culto y tesorería (1 Cr 23:7; 26:21; 2 Cr 29:12). Las traducciones tratan uniformemente este término como una designación propia de clan: español «gersonitas», francés y alemán «Gershonite/Gersoniter».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1650', 'spa', 'Gesur: reino arameo al este del alto Jordán, patria de Maaca, madre de Absalón (2 Sam 3:3).', 'Gesur era un pequeño reino arameo situado al este del mar de Galilea, en la región que después se conocería como el Golán. Su papel más memorable en las Escrituras es como patria de Maaca, hija de Talmai, una de las esposas de David y madre de Absalón (2 Sam 3:3). Cuando Absalón huyó tras asesinar a su medio hermano Amnón, se refugió en Gesur durante tres años bajo la protección de su abuelo (2 Sam 13:37-38). Josué señala que Israel nunca expulsó a los gesureos, quienes siguieron habitando entre los israelitas (Jos 13:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1651', 'spa', 'Gesureo; gentilicio que designa a los habitantes de Gesur, territorio arameo al este del Jordán y del mar de Galilea', 'Adjetivo gentilicio usado como sustantivo para designar a los habitantes de Gesur, un pequeño reino arameo situado al este del mar de Galilea. Los gesureos aparecen en contextos que describen territorios que Israel no conquistó durante el período de asentamiento. Deuteronomio 3:14 y Josué 13:11-13 señalan que los gesureos y los maacateos permanecieron sin ser conquistados entre los israelitas. Un segundo grupo con el mismo gentilicio aparece cerca del territorio filisteo (Jos 13:2; cf. 1 Sam 27:8), aunque algunos eruditos proponen enmiendas textuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1653', 'spa', 'Sustantivo hebreo estándar para la lluvia en todas sus manifestaciones ordinarias: desde las lluvias del diluvio de Noé (Gn 7:12) hasta los aguaceros ', 'Sustantivo hebreo estándar para la lluvia en todas sus manifestaciones ordinarias: desde las lluvias del diluvio de Noé (Gn 7:12) hasta los aguaceros estacionales prometidos por la obediencia al pacto (Lv 26:4) y la imagen profética de la palabra de Dios que desciende como lluvia (Is 55:10). Aparece en cadenas constructas (''lluvia del SEÑOR'', Job 37:6) y en la narrativa dramática de Elías en el Carmelo (''el sonido de abundancia de lluvia'', 1 R 18:41). Una ocurrencia en Zacarías 10:1 lleva fuerza intensificada — ''aguacero'' lo distingue de la lluvia ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1654', 'spa', 'Gesem (Gasmu); adversario árabe de Nehemías que se opuso a la reconstrucción de los muros de Jerusalén.', 'Nombre propio que identifica a un adversario árabe de Nehemías durante la reconstrucción postexílica de Jerusalén. Llamado «el árabe» (ha-Araví), Gesem se unió a Sanbalat y Tobías para burlarse y oponerse al proyecto de reconstrucción de la muralla. La forma alternativa Gasmu aparece en Nehemías 6:6, posiblemente reflejando una pronunciación aramea o nabatea. Las traducciones en español preservan ambas grafías (Gesem/Gasmu), evidenciando la variación escribal atestiguada en el texto hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1655', 'spa', 'cuerpo; la forma física de una persona o criatura (arameo, usado exclusivamente en Daniel)', 'Sustantivo arameo que significa ''cuerpo'', referido a la forma física y corpórea de un ser humano u otra criatura. Se encuentra exclusivamente en el libro de Daniel, donde aparece en contextos narrativos vívidos: los cuerpos de Sadrac, Mesac y Abednego intactos por el fuego (Dan 3:27-28), el cuerpo de Nabucodonosor empapado de rocío durante su período de locura (Dan 4:33; 5:21), y la bestia cuyo cuerpo es destruido en la visión de Daniel (Dan 7:11). La palabra es cognada del siríaco ''gushma'' y del arameo targúmico ''gushma'', que significan ''cuerpo'' o ''persona''.');